import type { RawQ } from "../types";
// Muṣṭalaḥ al-ḥadīth: chain and text, grades, kinds of weak reports, narrator criticism, transmission, key works. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "hdt-001", s: "hadith", g: 1, d: 1, t: ["sanad-matn", "terminology"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, on the definition of the isnād",
    en: ["In hadith terminology, what is the sanad?", ["The chain of narrators leading up to the text", "The wording of the report itself", "The book in which the report is recorded", "The explanation of the report's meaning"], "The sanad (or isnād) is the chain of people who transmitted the report, one from another, until it reaches its source. The wording that follows the chain is the matn."],
    de: ["Was ist in der Hadith-Terminologie der Sanad?", ["Die Kette der Überlieferer bis zum Text", "Der Wortlaut des Berichts selbst", "Das Buch, in dem der Bericht steht", "Die Erklärung der Bedeutung des Berichts"], "Der Sanad (oder Isnād) ist die Kette der Personen, die den Bericht einer vom anderen weitergegeben haben, bis zu seinem Ursprung. Der Wortlaut nach der Kette heißt Matn."],
    ar: ["ما السند في اصطلاح المحدثين؟", ["سلسلة الرواة الموصلة إلى المتن", "ألفاظ الحديث نفسها", "الكتاب الذي دُوِّن فيه الحديث", "شرح معنى الحديث"], "السند هو سلسلة الرجال الذين نقلوا الحديث بعضهم عن بعض حتى يصل إلى مصدره، وأما الكلام الذي ينتهي إليه السند فهو المتن."] },

  { id: "hdt-002", s: "hadith", g: 1, d: 1, t: ["sanad-matn", "terminology"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, on the matn",
    en: ["What is the matn of a hadith?", ["The words at which the chain of narrators ends", "The first narrator named at the start of the chain", "The list of teachers from whom the narrators heard", "The grading given to the report by a later critic"], "The matn is the actual content of the report: the speech or description at which the isnād ends. The isnād is only the route by which that text reached us."],
    de: ["Was ist der Matn eines Hadith?", ["Der Wortlaut, bei dem die Überliefererkette endet", "Der erste Überlieferer am Anfang der Kette", "Die Liste der Lehrer, von denen die Überlieferer hörten", "Die Bewertung des Berichts durch einen späteren Kritiker"], "Der Matn ist der eigentliche Inhalt des Berichts: die Rede oder Beschreibung, bei der der Isnād endet. Der Isnād ist nur der Weg, auf dem dieser Text zu uns gelangt ist."],
    ar: ["ما المتن في الحديث؟", ["ما ينتهي إليه السند من الكلام", "أول راوٍ يُذكر في أول السند", "قائمة الشيوخ الذين سمع منهم الرواة", "الحكم الذي يصدره الناقد على الحديث"], "المتن هو ما ينتهي إليه السند من الكلام، أي مضمون الحديث نفسه، وأما السند فهو الطريق الموصل إليه."] },

  { id: "hdt-003", s: "hadith", g: 1, d: 1, t: ["attribution-levels", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the marfūʿ",
    en: ["A report attributed to the Prophet (peace be upon him), whether a saying, an action or a tacit approval, is called:", ["Marfūʿ", "Mawqūf", "Maqṭūʿ", "Mursal"], "Marfūʿ means 'raised' to the Prophet. Mawqūf stops at a Companion and maqṭūʿ at a Successor; mursal describes a gap in the chain, not the level of attribution."],
    de: ["Ein Bericht, der dem Propheten (Friede sei mit ihm) zugeschrieben wird, sei es ein Wort, eine Handlung oder eine stillschweigende Billigung, heißt:", ["Marfūʿ", "Mawqūf", "Maqṭūʿ", "Mursal"], "Marfūʿ bedeutet „zum Propheten erhoben“. Mawqūf endet bei einem Gefährten, maqṭūʿ bei einem Nachfolger; mursal beschreibt eine Lücke in der Kette, nicht die Ebene der Zuschreibung."],
    ar: ["ما أُضيف إلى النبي صلى الله عليه وسلم من قول أو فعل أو تقرير يسمى:", ["المرفوع", "الموقوف", "المقطوع", "المرسل"], "المرفوع ما أضيف إلى النبي صلى الله عليه وسلم، والموقوف ما أضيف إلى الصحابي، والمقطوع ما أضيف إلى التابعي فمن دونه، وأما المرسل فوصف لسقط في السند لا لجهة الإضافة."] },

  { id: "hdt-004", s: "hadith", g: 1, d: 2, t: ["attribution-levels", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the mawqūf",
    en: ["A saying or action attributed to a Companion, without being attributed to the Prophet, is called:", ["Mawqūf", "Marfūʿ", "Maqṭūʿ", "Musnad"], "Mawqūf means 'stopped': the report stops at the Companion. If it went up to the Prophet it would be marfūʿ; if it stopped at a Successor it would be maqṭūʿ."],
    de: ["Ein Wort oder eine Handlung, die einem Gefährten zugeschrieben wird, ohne sie dem Propheten zuzuschreiben, heißt:", ["Mawqūf", "Marfūʿ", "Maqṭūʿ", "Musnad"], "Mawqūf bedeutet „angehalten“: Der Bericht endet beim Gefährten. Ginge er bis zum Propheten, wäre er marfūʿ; endete er bei einem Nachfolger, wäre er maqṭūʿ."],
    ar: ["ما أُضيف إلى الصحابي من قول أو فعل ولم يُرفع إلى النبي صلى الله عليه وسلم يسمى:", ["الموقوف", "المرفوع", "المقطوع", "المسند"], "الموقوف ما وُقف به على الصحابي، فلو رُفع إلى النبي صلى الله عليه وسلم لكان مرفوعًا، ولو وقف على التابعي لكان مقطوعًا."] },

  { id: "hdt-005", s: "hadith", g: 1, d: 2, t: ["attribution-levels", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the maqṭūʿ",
    en: ["A saying attributed to a Successor (tābiʿī) or someone after him is called:", ["Maqṭūʿ", "Munqaṭiʿ", "Mawqūf", "Muʿḍal"], "Maqṭūʿ concerns whose words the report contains (a Successor or later). Munqaṭiʿ and muʿḍal, by contrast, describe narrators missing from the chain."],
    de: ["Ein Wort, das einem Nachfolger (Tābiʿī) oder einem Späteren zugeschrieben wird, heißt:", ["Maqṭūʿ", "Munqaṭiʿ", "Mawqūf", "Muʿḍal"], "Maqṭūʿ betrifft, wessen Worte der Bericht enthält (ein Nachfolger oder später). Munqaṭiʿ und muʿḍal beschreiben dagegen fehlende Überlieferer in der Kette."],
    ar: ["ما أُضيف إلى التابعي فمن دونه من قول أو فعل يسمى:", ["المقطوع", "المنقطع", "الموقوف", "المعضل"], "المقطوع وصف لمن يُنسب إليه الكلام وهو التابعي فمن دونه، أما المنقطع والمعضل فوصفان لسقط الرواة من الإسناد."] },

  { id: "hdt-006", s: "hadith", g: 1, d: 1, t: ["hadith-qudsi", "terminology"], src: "al-Jurjānī, al-Taʿrīfāt, entry al-ḥadīth al-qudsī",
    en: ["What is a ḥadīth qudsī?", ["A report the Prophet relates from Allah, which is not Quran", "A verse of the Quran that the Prophet explained to the Companions", "A report that was narrated only in Jerusalem by its scholars", "Any hadith that speaks about the virtues of the earlier prophets"], "In a ḥadīth qudsī the Prophet attributes the content to Allah. It is nevertheless not part of the Quran and does not take the Quran's rulings."],
    de: ["Was ist ein Ḥadīth Qudsī?", ["Ein Bericht des Propheten von Allah, der kein Koran ist", "Ein Koranvers, den der Prophet den Gefährten erklärt hat", "Ein Bericht, der nur von Gelehrten in Jerusalem überliefert wurde", "Jeder Hadith über die Vorzüge der früheren Propheten"], "In einem Ḥadīth Qudsī schreibt der Prophet den Inhalt Allah zu. Dennoch ist er nicht Teil des Korans und hat nicht dessen Bestimmungen."],
    ar: ["ما الحديث القدسي؟", ["ما يرويه النبي صلى الله عليه وسلم عن ربه وليس قرآنًا", "آية من القرآن فسرها النبي صلى الله عليه وسلم لأصحابه", "حديث لم يروه إلا علماء بيت المقدس", "كل حديث ورد في فضائل الأنبياء السابقين"], "الحديث القدسي ما أضافه النبي صلى الله عليه وسلم إلى الله تعالى، ومع ذلك فليس من القرآن ولا تثبت له أحكامه."] },

  { id: "hdt-007", s: "hadith", g: 1, d: 1, t: ["sahih", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, opening on the division into ṣaḥīḥ, ḥasan and ḍaʿīf",
    en: ["Of the three basic grades of hadith, which is the highest?", ["Ṣaḥīḥ", "Ḥasan", "Ḍaʿīf", "Gharīb"], "Ibn al-Ṣalāḥ divides hadith into ṣaḥīḥ, ḥasan and ḍaʿīf, with ṣaḥīḥ at the top. Gharīb refers to the number of routes, not to a grade of acceptance."],
    de: ["Welche der drei Grundstufen des Hadith ist die höchste?", ["Ṣaḥīḥ", "Ḥasan", "Ḍaʿīf", "Gharīb"], "Ibn al-Ṣalāḥ teilt den Hadith in ṣaḥīḥ, ḥasan und ḍaʿīf ein, mit ṣaḥīḥ an der Spitze. Gharīb bezieht sich auf die Zahl der Überlieferungswege, nicht auf eine Stufe der Annahme."],
    ar: ["ما أعلى الأقسام الثلاثة الأساسية للحديث؟", ["الصحيح", "الحسن", "الضعيف", "الغريب"], "قسّم ابن الصلاح الحديث إلى صحيح وحسن وضعيف وأعلاها الصحيح، وأما الغريب فوصف لعدد الطرق لا مرتبة من مراتب القبول."] },

  { id: "hdt-008", s: "hadith", g: 1, d: 1, t: ["fabrication", "daif"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the mawḍūʿ",
    en: ["What is a mawḍūʿ hadith?", ["A fabricated report falsely ascribed to the Prophet", "A report from whose chain exactly one narrator is missing", "A report that goes back only to a Companion's own words", "A report whose chain includes a slightly weak narrator"], "Mawḍūʿ means invented and falsely ascribed to the Prophet. It is the worst kind of weak report; strictly speaking it is not a hadith at all."],
    de: ["Was ist ein Mawḍūʿ-Hadith?", ["Ein erfundener, dem Propheten fälschlich zugeschriebener Bericht", "Ein Bericht, in dessen Kette genau ein Überlieferer fehlt", "Ein Bericht, der nur auf die Worte eines Gefährten zurückgeht", "Ein Bericht, in dessen Kette ein leicht schwacher Überlieferer steht"], "Mawḍūʿ bedeutet erfunden und dem Propheten fälschlich zugeschrieben. Es ist die schlimmste Art des schwachen Berichts; genau genommen ist er gar kein Hadith."],
    ar: ["ما الحديث الموضوع؟", ["المختلق المكذوب على النبي صلى الله عليه وسلم", "ما سقط من إسناده راوٍ واحد فقط", "ما انتهى إلى قول الصحابي ولم يُرفع", "ما في إسناده راوٍ خفيف الضبط قليلًا"], "الموضوع هو المختلق المصنوع المنسوب إلى النبي صلى الله عليه وسلم كذبًا، وهو شر أنواع الضعيف، بل ليس حديثًا في الحقيقة."] },

  { id: "hdt-009", s: "hadith", g: 1, d: 2, t: ["companions", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the definition of the Companion",
    en: ["According to the definition preferred by Ibn Ḥajar, who is a Companion (ṣaḥābī)?", ["Someone who met the Prophet as a believer and died as a Muslim", "Someone who lived in Medina during the Prophet's lifetime", "Someone who accompanied the Prophet for at least a year", "Someone who narrated at least one hadith from the Prophet"], "Ibn Ḥajar defines the Companion as one who met the Prophet while believing in him and died in Islam. Long companionship or narrating hadith is not a condition."],
    de: ["Wer ist nach der von Ibn Ḥajar bevorzugten Definition ein Gefährte (Ṣaḥābī)?", ["Wer dem Propheten als Gläubiger begegnete und als Muslim starb", "Wer zu Lebzeiten des Propheten in Medina wohnte", "Wer den Propheten mindestens ein Jahr begleitete", "Wer mindestens einen Hadith vom Propheten überlieferte"], "Ibn Ḥajar definiert den Gefährten als jemanden, der dem Propheten begegnete, während er an ihn glaubte, und im Islam starb. Lange Begleitung oder das Überliefern von Hadithen ist keine Bedingung."],
    ar: ["من الصحابي على التعريف الذي رجحه ابن حجر؟", ["من لقي النبي صلى الله عليه وسلم مؤمنًا به ومات على الإسلام", "من سكن المدينة في حياة النبي صلى الله عليه وسلم", "من صحب النبي صلى الله عليه وسلم سنة فأكثر", "من روى عن النبي صلى الله عليه وسلم حديثًا واحدًا على الأقل"], "عرّف ابن حجر الصحابي بأنه من لقي النبي صلى الله عليه وسلم مؤمنًا به ومات على الإسلام، ولا يشترط طول الصحبة ولا الرواية."] },

  { id: "hdt-010", s: "hadith", g: 1, d: 2, t: ["companions", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the Successor",
    en: ["Who is a Successor (tābiʿī)?", ["A Muslim who met a Companion and died as a Muslim", "Anyone born after the death of the Prophet", "A student of one of the four imams", "A Companion who converted after the conquest of Mecca"], "The tābiʿī is defined in relation to the Companions: he met a Companion while Muslim and died in Islam. Being born after the Prophet's death is not enough without such a meeting."],
    de: ["Wer ist ein Nachfolger (Tābiʿī)?", ["Ein Muslim, der einem Gefährten begegnete und als Muslim starb", "Jeder, der nach dem Tod des Propheten geboren wurde", "Ein Schüler eines der vier Imame", "Ein Gefährte, der nach der Eroberung Mekkas Muslim wurde"], "Der Tābiʿī wird über die Gefährten bestimmt: Er begegnete als Muslim einem Gefährten und starb im Islam. Die Geburt nach dem Tod des Propheten genügt ohne eine solche Begegnung nicht."],
    ar: ["من التابعي؟", ["من لقي الصحابي مسلمًا ومات على الإسلام", "كل من وُلد بعد وفاة النبي صلى الله عليه وسلم", "تلميذ أحد الأئمة الأربعة", "صحابي أسلم بعد فتح مكة"], "التابعي من لقي صحابيًا مسلمًا ومات على الإسلام، فالمعتبر لقاء الصحابي لا مجرد الولادة بعد وفاة النبي صلى الله عليه وسلم."] },

  { id: "hdt-011", s: "hadith", g: 1, d: 2, t: ["mutawatir-ahad", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the mutawātir",
    en: ["What is a mutawātir report?", ["One narrated at every level by too many to have agreed on a lie", "One narrated by exactly two reliable narrators at every level", "One narrated by a single trustworthy narrator of excellent memory", "One recorded by both al-Bukhārī and Muslim in their two Ṣaḥīḥs"], "Tawātur requires a large number at every stage of the chain such that collusion on falsehood is ruled out by normal experience, ending in sense perception. Being in both Ṣaḥīḥs does not make a report mutawātir."],
    de: ["Was ist ein Mutawātir-Bericht?", ["Einer, den auf jeder Stufe zu viele für eine verabredete Lüge überliefern", "Einer, den auf jeder Stufe genau zwei zuverlässige Überlieferer weitergeben", "Einer, den ein einziger vertrauenswürdiger Überlieferer mit bestem Gedächtnis weitergibt", "Einer, den sowohl al-Bukhārī als auch Muslim in ihren Ṣaḥīḥ-Werken aufgenommen haben"], "Tawātur verlangt auf jeder Stufe der Kette eine große Zahl, bei der eine Verabredung zur Lüge nach gewöhnlicher Erfahrung ausgeschlossen ist, und die auf Sinneswahrnehmung beruht. Das Vorkommen in beiden Ṣaḥīḥ-Werken macht einen Bericht nicht mutawātir."],
    ar: ["ما الحديث المتواتر؟", ["ما رواه في كل طبقة جمع يستحيل تواطؤهم على الكذب", "ما رواه في كل طبقة ثقتان اثنان لا أكثر", "ما رواه ثقة واحد منفرد قوي الحفظ", "ما أخرجه البخاري ومسلم في صحيحيهما"], "المتواتر ما رواه جمع كثير في كل طبقة من طبقات السند تحيل العادة تواطؤهم على الكذب، وكان مستندهم الحس، وليس كل ما اتفق عليه الشيخان متواترًا."] },

  { id: "hdt-012", s: "hadith", g: 1, d: 2, t: ["key-works", "nukhbat-al-fikar"], src: "Ibn Ḥajar, Nukhbat al-Fikar, introduction",
    en: ["Who wrote Nukhbat al-Fikar, the concise text on hadith terminology?", ["Ibn Ḥajar al-ʿAsqalānī", "Ibn al-Ṣalāḥ", "Yaḥyā ibn Sharaf al-Nawawī", "Jalāl al-Dīn al-Suyūṭī"], "Nukhbat al-Fikar is by Ibn Ḥajar al-ʿAsqalānī, who also wrote its commentary Nuzhat al-Naẓar. Ibn al-Ṣalāḥ wrote the earlier Muqaddima."],
    de: ["Wer verfasste Nukhbat al-Fikar, den knappen Text zur Hadith-Terminologie?", ["Ibn Ḥajar al-ʿAsqalānī", "Ibn al-Ṣalāḥ", "Yaḥyā ibn Sharaf al-Nawawī", "Jalāl al-Dīn al-Suyūṭī"], "Nukhbat al-Fikar stammt von Ibn Ḥajar al-ʿAsqalānī, der dazu auch den Kommentar Nuzhat al-Naẓar schrieb. Ibn al-Ṣalāḥ verfasste die frühere Muqaddima."],
    ar: ["من مؤلف نخبة الفكر في مصطلح الحديث؟", ["ابن حجر العسقلاني", "ابن الصلاح", "يحيى بن شرف النووي", "جلال الدين السيوطي"], "نخبة الفكر لابن حجر العسقلاني، وله عليها شرح نزهة النظر، وأما ابن الصلاح فصاحب المقدمة المتقدمة عليها."] },

  { id: "hdt-013", s: "hadith", g: 1, d: 2, t: ["key-works", "bayquniyya"], src: "al-Bayqūnī, al-Manẓūma al-Bayqūniyya",
    en: ["What kind of work is al-Bayqūniyya?", ["A short teaching poem on the terms of hadith", "A commentary on the Ṣaḥīḥ of al-Bukhārī", "A biographical dictionary of hadith narrators", "A collection of forty hadiths with brief notes"], "Al-Bayqūniyya is a brief poem listing the main types of hadith in verse. Its brevity made it a common first text for students of muṣṭalaḥ."],
    de: ["Was für ein Werk ist al-Bayqūniyya?", ["Ein kurzes Lehrgedicht über die Hadith-Fachbegriffe", "Ein Kommentar zum Ṣaḥīḥ von al-Bukhārī", "Ein biographisches Lexikon der Hadith-Überlieferer", "Eine Sammlung von vierzig Hadithen mit kurzen Anmerkungen"], "Al-Bayqūniyya ist ein kurzes Gedicht, das die wichtigsten Hadith-Arten in Versen aufzählt. Wegen seiner Kürze ist es ein verbreiteter erster Text für Studierende des Muṣṭalaḥ."],
    ar: ["ما نوع المنظومة البيقونية؟", ["منظومة قصيرة في مصطلح الحديث", "شرح على صحيح الإمام البخاري", "معجم في تراجم رواة الحديث", "مجموع أربعين حديثًا مع تعليقات"], "البيقونية منظومة قصيرة نظم فيها صاحبها أهم أنواع الحديث، ولقصرها صارت من أول ما يحفظه طالب المصطلح."] },

  { id: "hdt-014", s: "hadith", g: 1, d: 1, t: ["transmission-methods", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ways of receiving hadith",
    en: ["What is samāʿ as a way of receiving hadith?", ["The student hears the teacher narrating the hadith", "The student reads the hadith to the teacher", "The teacher gives written permission to narrate", "The student finds the hadith in a teacher's handwriting"], "In samāʿ the teacher narrates, from memory or from his book, and the student listens. Reading to the teacher is qirāʾa, permission is ijāza and finding a text is wijāda."],
    de: ["Was ist Samāʿ als Weg der Hadith-Aufnahme?", ["Der Schüler hört, wie der Lehrer den Hadith vorträgt", "Der Schüler liest dem Lehrer den Hadith vor", "Der Lehrer gibt eine schriftliche Erlaubnis zur Überlieferung", "Der Schüler findet den Hadith in der Handschrift eines Lehrers"], "Beim Samāʿ trägt der Lehrer aus dem Gedächtnis oder aus seinem Buch vor, und der Schüler hört zu. Das Vorlesen vor dem Lehrer ist Qirāʾa, die Erlaubnis Ijāza und das Auffinden eines Textes Wijāda."],
    ar: ["ما السماع من طرق تحمل الحديث؟", ["أن يسمع الطالب لفظ الشيخ وهو يحدث", "أن يقرأ الطالب على الشيخ", "أن يأذن الشيخ كتابةً بالرواية", "أن يجد الطالب الحديث بخط شيخ"], "السماع أن يحدث الشيخ من حفظه أو من كتابه والطالب يسمع، وأما القراءة على الشيخ فعرض، والإذن إجازة، والعثور على الخط وجادة."] },

  { id: "hdt-015", s: "hadith", g: 1, d: 2, t: ["jarh-tadil", "narrator-conditions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on who is accepted as a narrator",
    en: ["In narrator criticism, what does ʿadāla refer to?", ["Uprightness in religion and conduct", "Strength and precision of memory", "The number of a narrator's teachers", "Reaching an advanced age"], "ʿAdāla concerns the narrator's character: being a sane, adult Muslim, free of open sin and of what damages decency. Precision of memory is the separate condition of ḍabṭ."],
    de: ["Worauf bezieht sich ʿAdāla in der Überliefererkritik?", ["Auf die Rechtschaffenheit in Religion und Lebensführung", "Auf die Stärke und Genauigkeit des Gedächtnisses", "Auf die Zahl der Lehrer eines Überlieferers", "Auf das Erreichen eines hohen Alters"], "ʿAdāla betrifft den Charakter: ein verständiger, mündiger Muslim zu sein, frei von offenkundiger Sünde und von dem, was den Anstand verletzt. Die Genauigkeit des Gedächtnisses ist die gesonderte Bedingung Ḍabṭ."],
    ar: ["ما المراد بالعدالة في نقد الرواة؟", ["الاستقامة في الدين والمروءة", "قوة الحفظ وإتقان المرويات", "كثرة الشيوخ الذين سمع منهم", "بلوغ الراوي سنًّا متقدمة"], "العدالة صفة في الدين والخلق: أن يكون الراوي مسلمًا بالغًا عاقلًا سالمًا من أسباب الفسق وخوارم المروءة، وأما إتقان الحفظ فهو الضبط."] },

  { id: "hdt-016", s: "hadith", g: 1, d: 2, t: ["jarh-tadil", "narrator-conditions"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, on ḍabṭ",
    en: ["Ibn Ḥajar divides ḍabṭ (precision) into two kinds. What are they?", ["Precision of memory and precision of the written book", "Precision of grammar and precision of meaning", "Precision in the chain and precision in the text", "Precision in youth and precision in old age"], "Ḍabṭ al-ṣadr means the narrator retains what he heard so he can recall it at will; ḍabṭ al-kitāb means he keeps his written copy sound from the time he heard until he narrates from it."],
    de: ["Ibn Ḥajar teilt Ḍabṭ (Genauigkeit) in zwei Arten. Welche?", ["Genauigkeit des Gedächtnisses und Genauigkeit des Buches", "Genauigkeit der Grammatik und Genauigkeit der Bedeutung", "Genauigkeit in der Kette und Genauigkeit im Text", "Genauigkeit in der Jugend und Genauigkeit im Alter"], "Ḍabṭ al-ṣadr bedeutet, dass der Überlieferer das Gehörte so bewahrt, dass er es jederzeit wiedergeben kann; Ḍabṭ al-kitāb bedeutet, dass er seine Niederschrift vom Hören bis zum Weitergeben fehlerfrei hält."],
    ar: ["قسم ابن حجر الضبط قسمين، فما هما؟", ["ضبط الصدر وضبط الكتاب", "ضبط الإعراب وضبط المعنى", "ضبط السند وضبط المتن", "ضبط الشباب وضبط الكبر"], "ضبط الصدر أن يثبت الراوي ما سمعه بحيث يتمكن من استحضاره متى شاء، وضبط الكتاب صيانته لديه منذ سمع فيه إلى أن يؤدي منه."] },

  { id: "hdt-017", s: "hadith", g: 1, d: 1, t: ["terminology", "sanad-matn"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, introduction",
    en: ["What is the subject of the science of muṣṭalaḥ al-ḥadīth?", ["Rules for judging whether a chain and text are accepted", "The explanation of rare and difficult words in hadith", "The history of the early Islamic conquests and battles", "The rulings of worship that are derived from hadith"], "Muṣṭalaḥ al-ḥadīth studies the chain and text in order to judge acceptance or rejection. Explaining words or deriving rulings belong to other disciplines (gharīb al-ḥadīth, fiqh al-ḥadīth)."],
    de: ["Womit befasst sich die Wissenschaft des Muṣṭalaḥ al-Ḥadīth?", ["Mit den Regeln, ob Kette und Text angenommen oder abgelehnt werden", "Mit der Erklärung schwieriger Wörter im Hadith", "Mit der Geschichte der islamischen Eroberungen", "Mit den aus dem Hadith abgeleiteten Bestimmungen zum Gottesdienst"], "Muṣṭalaḥ al-Ḥadīth untersucht Kette und Text, um über Annahme oder Ablehnung zu urteilen. Worterklärung und Normableitung gehören zu anderen Fächern (Gharīb al-Ḥadīth, Fiqh al-Ḥadīth)."],
    ar: ["ما موضوع علم مصطلح الحديث؟", ["قواعد يعرف بها حال السند والمتن قبولًا وردًا", "شرح الألفاظ الغريبة الواردة في الأحاديث", "تاريخ الفتوحات والغزوات الإسلامية الأولى", "الأحكام الفقهية المستنبطة من الأحاديث"], "علم المصطلح قواعد يعرف بها حال السند والمتن من حيث القبول والرد، وأما شرح الغريب واستنباط الأحكام فمن علوم أخرى."] },

  { id: "hdt-018", s: "hadith", g: 1, d: 2, t: ["terminology", "attribution-levels"], src: "al-Nawawī, al-Taqrīb wa-l-Taysīr, the type on the mawqūf",
    en: ["Al-Nawawī notes that the jurists of Khurasan used the word athar for a particular kind of report. Which one?", ["Reports stopping at a Companion (mawqūf)", "Reports narrated by many (mutawātir)", "Reports with a fabricated text", "Reports about the Prophet's appearance"], "According to al-Nawawī, the Khurasan jurists called the mawqūf athar and the marfūʿ khabar, while the hadith scholars applied athar to both."],
    de: ["Al-Nawawī erwähnt, dass die Rechtsgelehrten Chorasans das Wort Athar für eine bestimmte Art von Bericht verwendeten. Für welche?", ["Für Berichte, die bei einem Gefährten enden (mawqūf)", "Für Berichte, die von vielen überliefert sind (mutawātir)", "Für Berichte mit erfundenem Text", "Für Berichte über das Aussehen des Propheten"], "Nach al-Nawawī nannten die Rechtsgelehrten Chorasans das Mawqūf Athar und das Marfūʿ Khabar, während die Hadith-Gelehrten Athar für beides verwendeten."],
    ar: ["ذكر النووي أن فقهاء خراسان يخصون لفظ الأثر بنوع من المرويات، فما هو؟", ["الموقوف على الصحابي", "المتواتر", "المكذوب المتن", "ما ورد في صفة النبي صلى الله عليه وسلم"], "ذكر النووي أن فقهاء خراسان يسمون الموقوف أثرًا والمرفوع خبرًا، وأما المحدثون فيطلقون الأثر على المرفوع والموقوف جميعًا."] },

  { id: "hdt-019", s: "hadith", g: 2, d: 2, t: ["mutawatir-ahad", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the mashhūr",
    en: ["Which report is called mashhūr in Ibn Ḥajar's classification?", ["More than two narrators at every level, short of tawātur", "Exactly two narrators at every level of the whole chain", "A single narrator at one level, more at the other levels", "So many narrators at every level that lying is impossible"], "Ibn Ḥajar defines the mashhūr as an āḥād report with more than two routes, without reaching the conditions of tawātur. Exactly two is ʿazīz, one is gharīb."],
    de: ["Welcher Bericht heißt in Ibn Ḥajars Einteilung mashhūr?", ["Mehr als zwei Überlieferer auf jeder Stufe, ohne Tawātur", "Genau zwei Überlieferer auf jeder Stufe der ganzen Kette", "Ein einziger Überlieferer auf einer Stufe, sonst mehrere", "So viele Überlieferer auf jeder Stufe, dass Lüge unmöglich ist"], "Ibn Ḥajar definiert das Mashhūr als Āḥād-Bericht mit mehr als zwei Wegen, ohne die Bedingungen des Tawātur zu erfüllen. Genau zwei ergibt ʿazīz, einer gharīb."],
    ar: ["ما المشهور في تقسيم ابن حجر؟", ["ما رواه أكثر من اثنين في كل طبقة دون التواتر", "ما رواه اثنان فقط في كل طبقة من طبقاته", "ما انفرد به راوٍ واحد في طبقة من طبقاته", "ما رواه جمع يستحيل تواطؤهم على الكذب"], "المشهور عند ابن حجر ما له طرق محصورة بأكثر من اثنين ولم يبلغ حد التواتر، والعزيز ما لا يقل رواته عن اثنين، والغريب ما ينفرد به واحد."] },

  { id: "hdt-020", s: "hadith", g: 2, d: 2, t: ["mutawatir-ahad", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the ʿazīz",
    en: ["According to Ibn Ḥajar, a report whose narrators are never fewer than two at any level of the chain is called:", ["ʿAzīz", "Gharīb", "Mashhūr", "Mutawātir"], "Ibn Ḥajar defines the ʿazīz as a report whose narrators do not fall below two at any stage. If one level has only one narrator it is gharīb."],
    de: ["Nach Ibn Ḥajar heißt ein Bericht, dessen Überlieferer auf keiner Stufe der Kette weniger als zwei sind:", ["ʿAzīz", "Gharīb", "Mashhūr", "Mutawātir"], "Ibn Ḥajar definiert das ʿAzīz als Bericht, dessen Überlieferer auf keiner Stufe unter zwei fallen. Hat eine Stufe nur einen Überlieferer, ist er gharīb."],
    ar: ["الحديث الذي لا يقل رواته عن اثنين في جميع طبقات السند يسمى عند ابن حجر:", ["العزيز", "الغريب", "المشهور", "المتواتر"], "العزيز عند ابن حجر ما لا يقل رواته عن اثنين في جميع طبقات السند، فإن انفرد به واحد في طبقة صار غريبًا."] },

  { id: "hdt-021", s: "hadith", g: 2, d: 2, t: ["mutawatir-ahad", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the gharīb",
    en: ["Which statement about a gharīb hadith is correct?", ["It has one narrator at some level and may still be ṣaḥīḥ", "It is always weak because it comes through only one route", "It is always fabricated because no other narrator knows it", "It must contain a rare or unusual word somewhere in its text"], "Gharīb describes the number of routes, not the grade. A gharīb report with a sound chain can be ṣaḥīḥ; the hadith on intentions is a well-known example of a ṣaḥīḥ gharīb report."],
    de: ["Welche Aussage über einen Gharīb-Hadith ist richtig?", ["Er hat auf einer Stufe nur einen Überlieferer und kann dennoch ṣaḥīḥ sein", "Er ist immer schwach, weil er nur über einen einzigen Weg kommt", "Er ist immer erfunden, weil ihn kein anderer Überlieferer kennt", "Er muss irgendwo in seinem Text ein seltenes, ungewöhnliches Wort enthalten"], "Gharīb beschreibt die Zahl der Wege, nicht die Bewertung. Ein Gharīb-Bericht mit gesunder Kette kann ṣaḥīḥ sein; der Hadith über die Absichten ist ein bekanntes Beispiel eines gesunden Gharīb-Berichts."],
    ar: ["أي العبارات صحيحة في الحديث الغريب؟", ["ينفرد به راوٍ في طبقة ما وقد يكون صحيحًا", "هو ضعيف دائمًا لأن له طريقًا واحدًا", "هو موضوع دائمًا لأنه لا يعرفه غيره", "لا بد أن يكون في متنه لفظ نادر"], "الغرابة وصف لعدد الطرق لا لدرجة الحديث، فقد يكون الغريب صحيحًا إذا صح إسناده، ومن أشهر أمثلته حديث النيات."] },

  { id: "hdt-022", s: "hadith", g: 2, d: 2, t: ["sahih", "sahih-conditions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ṣaḥīḥ",
    en: ["Which of the following is NOT one of the five conditions of a ṣaḥīḥ hadith?", ["Being narrated by at least two Companions", "A connected chain of narrators", "Narrators who are upright and precise", "Freedom from shudhūdh and hidden defects"], "The five conditions are a connected chain, upright narrators, precise narrators, absence of shudhūdh and absence of ʿilla. A single Companion's narration can be fully ṣaḥīḥ."],
    de: ["Welche der folgenden ist KEINE der fünf Bedingungen eines Ṣaḥīḥ-Hadith?", ["Die Überlieferung durch mindestens zwei Gefährten", "Eine zusammenhängende Überliefererkette", "Rechtschaffene und genaue Überlieferer", "Freiheit von Shudhūdh und verborgenen Mängeln"], "Die fünf Bedingungen sind eine zusammenhängende Kette, rechtschaffene Überlieferer, genaue Überlieferer, das Fehlen von Shudhūdh und das Fehlen einer ʿIlla. Die Überlieferung eines einzigen Gefährten kann vollständig ṣaḥīḥ sein."],
    ar: ["أيّ مما يلي ليس من شروط الحديث الصحيح الخمسة؟", ["أن يرويه صحابيان فأكثر", "اتصال السند", "عدالة الرواة وضبطهم", "السلامة من الشذوذ والعلة"], "شروط الصحيح خمسة: اتصال السند، وعدالة الرواة، وضبطهم، وعدم الشذوذ، وعدم العلة، ولا يشترط تعدد الصحابة، فرواية الصحابي الواحد قد تكون صحيحة."] },

  { id: "hdt-023", s: "hadith", g: 2, d: 3, t: ["sahih", "supporting-routes"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, on ṣaḥīḥ li-ghayrihi",
    en: ["What is ṣaḥīḥ li-ghayrihi?", ["A ḥasan li-dhātihi report raised to ṣaḥīḥ by other routes", "A ṣaḥīḥ report narrated from a Successor", "A weak report accepted because a scholar acted on it", "A ṣaḥīḥ report whose text was later shortened"], "When a report that is ḥasan in itself is supported by further routes of equal or greater strength, the combined support raises it to ṣaḥīḥ, but 'because of something else', not by its own chain."],
    de: ["Was ist Ṣaḥīḥ li-ghayrihi?", ["Ein Ḥasan-li-dhātihi-Bericht, der durch weitere Wege zu ṣaḥīḥ erhoben wird", "Ein gesunder Bericht, der von einem Nachfolger stammt", "Ein schwacher Bericht, der angenommen wird, weil ein Gelehrter danach handelte", "Ein gesunder Bericht, dessen Text später gekürzt wurde"], "Wird ein in sich ḥasan Bericht durch weitere gleich starke oder stärkere Wege gestützt, hebt ihn diese Stützung auf ṣaḥīḥ, jedoch „wegen anderem“, nicht durch die eigene Kette."],
    ar: ["ما الصحيح لغيره؟", ["الحسن لذاته إذا تعددت طرقه فارتقى", "الصحيح المروي من طريق تابعي واحد", "الضعيف الذي قُبل لعمل أحد العلماء به", "الصحيح الذي اختُصر متنه فيما بعد"], "الحسن لذاته إذا رُوي من طرق أخرى مثله أو أقوى منه ارتقى إلى الصحيح، لكن لغيره لا لذات إسناده."] },

  { id: "hdt-024", s: "hadith", g: 2, d: 3, t: ["hasan", "sahih-conditions"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the ḥasan li-dhātihi",
    en: ["In Ibn Ḥajar's definition, what distinguishes ḥasan li-dhātihi from ṣaḥīḥ li-dhātihi?", ["One of its narrators has somewhat lighter precision", "Its chain has one narrator missing", "It stops at a Companion instead of the Prophet", "It is supported only by a weak route"], "Ibn Ḥajar keeps all conditions of the ṣaḥīḥ for the ḥasan li-dhātihi except that the precision of a narrator is lighter. A missing narrator would make it munqaṭiʿ and weak."],
    de: ["Was unterscheidet nach Ibn Ḥajars Definition Ḥasan li-dhātihi von Ṣaḥīḥ li-dhātihi?", ["Einer der Überlieferer ist etwas weniger genau", "In der Kette fehlt an einer Stelle ein Überlieferer", "Er endet bei einem Gefährten statt beim Propheten", "Er wird nur durch einen einzigen schwachen Weg gestützt"], "Ibn Ḥajar behält für das Ḥasan li-dhātihi alle Bedingungen des Ṣaḥīḥ bei, nur ist die Genauigkeit eines Überlieferers geringer. Ein fehlender Überlieferer machte ihn munqaṭiʿ und schwach."],
    ar: ["بم يفترق الحسن لذاته عن الصحيح لذاته في تعريف ابن حجر؟", ["بخفة ضبط بعض رواته", "بسقوط راوٍ من إسناده", "بوقوفه على الصحابي دون النبي صلى الله عليه وسلم", "باعتضاده بطريق ضعيف فقط"], "الحسن لذاته عند ابن حجر ما اجتمعت فيه شروط الصحيح إلا أنه خفّ ضبط راويه، أما سقوط راوٍ فيجعله منقطعًا ضعيفًا."] },

  { id: "hdt-025", s: "hadith", g: 2, d: 3, t: ["hasan", "supporting-routes"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ḥasan",
    en: ["What is ḥasan li-ghayrihi?", ["A mildly weak report strengthened by similar routes", "A ṣaḥīḥ report whose text is slightly shorter than usual", "A fabricated report that later became famous among people", "A report that only a single Successor narrated from a Companion"], "A report whose weakness is not severe (for example a narrator of weak memory, not a liar) can rise to ḥasan li-ghayrihi when it comes through other routes. Severe weakness, such as fabrication, is not repaired by more routes."],
    de: ["Was ist Ḥasan li-ghayrihi?", ["Ein leicht schwacher, durch ähnliche Wege gestärkter Bericht", "Ein gesunder Bericht mit etwas kürzerem Text als üblich", "Ein erfundener Bericht, der später unter den Leuten bekannt wurde", "Ein Bericht, den nur ein einziger Nachfolger von einem Gefährten überlieferte"], "Ein Bericht, dessen Schwäche nicht schwer ist (etwa ein Überlieferer mit schwachem Gedächtnis, kein Lügner), kann durch weitere Wege zu Ḥasan li-ghayrihi aufsteigen. Schwere Schwäche wie Erfindung wird durch mehr Wege nicht behoben."],
    ar: ["ما الحسن لغيره؟", ["الضعيف يسيرًا إذا تعددت طرقه فتقوى", "الصحيح الذي جاء متنه أقصر من المعتاد", "الموضوع الذي اشتهر بين الناس فيما بعد", "ما انفرد بروايته تابعي واحد عن صحابي"], "الحسن لغيره هو الضعيف الذي ليس ضعفه شديدًا كسوء حفظ الراوي إذا جاء من طرق أخرى فتقوى بها، أما شديد الضعف كالموضوع فلا يتقوى بكثرة الطرق."] },

  { id: "hdt-026", s: "hadith", g: 2, d: 2, t: ["broken-chain", "mursal"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the mursal",
    en: ["In the well-known definition, what is a mursal hadith?", ["A Successor attributes a report directly to the Prophet", "A Companion attributes a report to another Companion", "A compiler drops his own teacher from the chain", "A narrator inserts his own words into the text"], "The mursal is a report in which a tābiʿī says 'the Prophet said' without naming the Companion he heard it from. Dropping from the compiler's end is muʿallaq; inserting words is idrāj."],
    de: ["Was ist nach der bekannten Definition ein Mursal-Hadith?", ["Ein Nachfolger schreibt einen Bericht direkt dem Propheten zu", "Ein Gefährte schreibt einen Bericht einem anderen Gefährten zu", "Ein Sammler lässt seinen eigenen Lehrer aus der Kette weg", "Ein Überlieferer fügt eigene Worte in den Text ein"], "Mursal ist ein Bericht, in dem ein Tābiʿī „der Prophet sagte“ sagt, ohne den Gefährten zu nennen, von dem er es hörte. Weglassen am Anfang beim Sammler ist muʿallaq; Einfügen von Worten ist Idrāj."],
    ar: ["ما الحديث المرسل في التعريف المشهور؟", ["ما رفعه التابعي إلى النبي صلى الله عليه وسلم", "ما نسبه صحابي إلى صحابي آخر من أقرانه", "ما حذف فيه المصنف شيخه من أول الإسناد", "ما أدرج فيه الراوي كلامه في متن الحديث"], "المرسل ما قال فيه التابعي: قال رسول الله صلى الله عليه وسلم، دون ذكر الصحابي الذي سمع منه، أما الحذف من مبدأ السند من جهة المصنف فهو المعلق، وإدخال الكلام إدراج."] },

  { id: "hdt-027", s: "hadith", g: 2, d: 2, t: ["broken-chain", "muallaq"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the muʿallaq",
    en: ["A report from whose chain one or more narrators are dropped at the compiler's end is called:", ["Muʿallaq", "Mursal", "Muʿḍal", "Mudallas"], "Muʿallaq ('suspended') means the omission is at the beginning of the chain, on the side of the author, sometimes up to the whole chain. Al-Bukhārī's ṣaḥīḥ contains such suspended reports in its chapter headings."],
    de: ["Ein Bericht, bei dem am Anfang der Kette, auf Seiten des Sammlers, einer oder mehrere Überlieferer weggelassen sind, heißt:", ["Muʿallaq", "Mursal", "Muʿḍal", "Mudallas"], "Muʿallaq („aufgehängt“) bedeutet, dass die Auslassung am Anfang der Kette beim Autor liegt, mitunter bis zur ganzen Kette. Al-Bukhārīs Ṣaḥīḥ enthält solche Berichte in seinen Kapitelüberschriften."],
    ar: ["ما حُذف من مبدأ إسناده من جهة المصنف راوٍ فأكثر يسمى:", ["المعلق", "المرسل", "المعضل", "المدلس"], "المعلق ما حذف من مبدأ إسناده راوٍ أو أكثر ولو إلى آخر الإسناد، وفي صحيح البخاري تعليقات كثيرة في تراجم الأبواب."] },

  { id: "hdt-028", s: "hadith", g: 2, d: 3, t: ["broken-chain", "mudal"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the muʿḍal",
    en: ["What is a muʿḍal hadith?", ["One with two or more consecutive narrators missing", "One with a single narrator missing at the end", "One with two narrators missing at separate places", "One with a narrator whose identity is unknown"], "Muʿḍal requires two or more narrators dropped in succession. Two dropped at different places, not in succession, is classed as munqaṭiʿ (in more than one place)."],
    de: ["Was ist ein Muʿḍal-Hadith?", ["Einer, bei dem zwei oder mehr aufeinanderfolgende Überlieferer fehlen", "Einer, bei dem am Ende ein einzelner Überlieferer fehlt", "Einer, bei dem zwei Überlieferer an getrennten Stellen fehlen", "Einer mit einem Überlieferer unbekannter Identität"], "Muʿḍal verlangt zwei oder mehr hintereinander ausgefallene Überlieferer. Fallen zwei an verschiedenen Stellen aus, gilt er als munqaṭiʿ (an mehreren Stellen)."],
    ar: ["ما الحديث المعضل؟", ["ما سقط من إسناده اثنان فأكثر على التوالي", "ما سقط من آخر إسناده راوٍ واحد", "ما سقط منه راويان في موضعين متفرقين", "ما فيه راوٍ مجهول العين"], "المعضل ما سقط من إسناده اثنان فصاعدًا مع التوالي، فإن سقطا في موضعين غير متواليين فهو منقطع من موضعين."] },

  { id: "hdt-029", s: "hadith", g: 2, d: 3, t: ["broken-chain", "munqati"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the munqaṭiʿ",
    en: ["In Ibn Ḥajar's classification, a chain from which a narrator has dropped in the middle, not in a consecutive pair, is called:", ["Munqaṭiʿ", "Muʿḍal", "Muʿallaq", "Mursal"], "Ibn Ḥajar sorts gaps by position: at the compiler's end it is muʿallaq, after the Successor mursal, two in succession muʿḍal, and otherwise munqaṭiʿ."],
    de: ["Wie heißt in Ibn Ḥajars Einteilung eine Kette, aus der in der Mitte ein Überlieferer ausgefallen ist, nicht als aufeinanderfolgendes Paar?", ["Munqaṭiʿ", "Muʿḍal", "Muʿallaq", "Mursal"], "Ibn Ḥajar ordnet Lücken nach ihrer Lage: am Anfang beim Sammler muʿallaq, nach dem Nachfolger mursal, zwei hintereinander muʿḍal, sonst munqaṭiʿ."],
    ar: ["ما سقط من وسط إسناده راوٍ لا على التوالي اثنين يسمى في تقسيم ابن حجر:", ["المنقطع", "المعضل", "المعلق", "المرسل"], "قسّم ابن حجر السقط بحسب موضعه: فإن كان من مبدأ السند فهو المعلق، أو من آخره بعد التابعي فهو المرسل، أو باثنين فصاعدًا مع التوالي فهو المعضل، وإلا فهو المنقطع."] },

  { id: "hdt-030", s: "hadith", g: 2, d: 3, t: ["attribution-levels", "broken-chain"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the maqṭūʿ",
    en: ["What is the difference between maqṭūʿ and munqaṭiʿ?", ["Maqṭūʿ concerns the speaker; munqaṭiʿ a gap in the chain", "Both mean a gap in the chain, but in maqṭūʿ the gap is longer", "Maqṭūʿ is always accepted, while munqaṭiʿ is always fabricated", "Both mean a Successor's saying, but from different regions"], "Maqṭūʿ describes the text: words of a Successor or later. Munqaṭiʿ describes the chain: a narrator is missing. A maqṭūʿ report can have a fully connected chain."],
    de: ["Worin unterscheiden sich Maqṭūʿ und Munqaṭiʿ?", ["Maqṭūʿ betrifft den Sprecher, Munqaṭiʿ eine Lücke in der Kette", "Beide bedeuten eine Lücke, doch bei Maqṭūʿ ist die Lücke länger", "Maqṭūʿ wird immer angenommen, Munqaṭiʿ ist dagegen stets erfunden", "Beide bedeuten das Wort eines Nachfolgers, nur aus verschiedenen Regionen"], "Maqṭūʿ beschreibt den Text: Worte eines Nachfolgers oder Späteren. Munqaṭiʿ beschreibt die Kette: Ein Überlieferer fehlt. Ein Maqṭūʿ-Bericht kann eine vollständig zusammenhängende Kette haben."],
    ar: ["ما الفرق بين المقطوع والمنقطع؟", ["المقطوع وصف للقائل، والمنقطع وصف لسقط في السند", "كلاهما سقط في السند، لكن السقط في المقطوع أطول", "المقطوع مقبول دائمًا، والمنقطع موضوع في كل حال", "كلاهما قول تابعي، لكن من بلدان مختلفة"], "المقطوع من مباحث المتن وهو ما أضيف إلى التابعي فمن دونه، والمنقطع من مباحث الإسناد وهو ما سقط منه راوٍ، وقد يكون المقطوع متصل الإسناد."] },

  { id: "hdt-031", s: "hadith", g: 2, d: 3, t: ["contradiction", "shadhdh"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the shādhdh and the maḥfūẓ",
    en: ["According to Ibn Ḥajar, what is a shādhdh report?", ["An acceptable narrator contradicting one more reliable than him", "A weak narrator contradicting reliable narrators", "A reliable narrator adding a word no one contradicts", "A narrator reporting something no one else has narrated"], "Ibn Ḥajar defines shādhdh as the report of an acceptable narrator that opposes someone weightier. When the contradicting narrator is weak, the result is munkar. A mere solitary narration is not shudhūdh by itself."],
    de: ["Was ist nach Ibn Ḥajar ein Shādhdh-Bericht?", ["Ein annehmbarer Überlieferer widerspricht einem Zuverlässigeren", "Ein schwacher Überlieferer widerspricht zuverlässigen Überlieferern", "Ein zuverlässiger Überlieferer fügt ein unwidersprochenes Wort hinzu", "Ein Überlieferer berichtet etwas, das sonst niemand überliefert"], "Ibn Ḥajar definiert Shādhdh als Bericht eines annehmbaren Überlieferers, der einem Gewichtigeren widerspricht. Ist der Widersprechende schwach, ist das Ergebnis munkar. Ein bloßes Alleinüberliefern ist für sich kein Shudhūdh."],
    ar: ["ما الشاذ عند ابن حجر؟", ["ما رواه المقبول مخالفًا لمن هو أولى منه", "ما رواه الضعيف مخالفًا للثقات", "ما زاده الثقة من لفظ لا يخالفه فيه أحد", "ما انفرد به راوٍ ولم يروه غيره"], "الشاذ عند ابن حجر ما رواه المقبول مخالفًا لمن هو أولى منه، فإن كان المخالف ضعيفًا فهو المنكر، ومجرد التفرد لا يسمى شذوذًا بهذا التعريف."] },

  { id: "hdt-032", s: "hadith", g: 2, d: 3, t: ["contradiction", "munkar"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the munkar and the maʿrūf",
    en: ["In Ibn Ḥajar's terminology, the report of a weak narrator that contradicts reliable narrators is called:", ["Munkar", "Shādhdh", "Muḍṭarib", "Mudraj"], "Ibn Ḥajar reserves munkar for a weak narrator's contradiction of the reliable; its opposite is called maʿrūf. When an acceptable narrator contradicts a weightier one, it is shādhdh."],
    de: ["Wie heißt in Ibn Ḥajars Terminologie der Bericht eines schwachen Überlieferers, der zuverlässigen widerspricht?", ["Munkar", "Shādhdh", "Muḍṭarib", "Mudraj"], "Ibn Ḥajar verwendet munkar für den Widerspruch eines Schwachen gegen Zuverlässige; das Gegenstück heißt maʿrūf. Widerspricht ein annehmbarer Überlieferer einem Gewichtigeren, ist es shādhdh."],
    ar: ["ما رواه الضعيف مخالفًا للثقات يسمى في اصطلاح ابن حجر:", ["المنكر", "الشاذ", "المضطرب", "المدرج"], "خص ابن حجر المنكر بما رواه الضعيف مخالفًا للثقة، ومقابله المعروف، أما مخالفة المقبول لمن هو أولى منه فهي الشذوذ."] },

  { id: "hdt-033", s: "hadith", g: 2, d: 3, t: ["hidden-defect", "muallal"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the muʿallal",
    en: ["What is a muʿallal hadith?", ["One with a hidden defect, though outwardly it looks sound", "One whose narrator is openly known as a liar by everyone", "One with an obvious gap at the very start of its chain", "One whose text contains a rare word needing explanation"], "The ʿilla is a concealed cause that damages soundness while the chain appears free of it; only expert critics detect it by gathering routes. An openly lying narrator is an apparent, not a hidden, defect."],
    de: ["Was ist ein Muʿallal-Hadith?", ["Einer mit verborgenem Mangel, obwohl er äußerlich gesund wirkt", "Einer, dessen Überlieferer offen als Lügner bekannt ist", "Einer mit offensichtlicher Lücke am Anfang der Kette", "Einer, dessen Text ein seltenes Wort enthält"], "Die ʿIlla ist eine verborgene Ursache, die die Gesundheit beeinträchtigt, während die Kette frei davon erscheint; nur erfahrene Kritiker erkennen sie durch das Sammeln der Wege. Ein offen lügender Überlieferer ist ein sichtbarer, kein verborgener Mangel."],
    ar: ["ما الحديث المعلل؟", ["ما فيه علة خفية قادحة مع سلامة ظاهره", "ما كان راويه معروفًا بالكذب عند الجميع", "ما في أول إسناده سقط ظاهر للناظر", "ما في متنه لفظ غريب يحتاج إلى شرح"], "المعلل ما اطُّلع فيه على علة خفية تقدح في صحته مع أن ظاهره السلامة منها، ولا يدركها إلا الحذاق بجمع الطرق، أما كذب الراوي فطعن ظاهر لا خفي."] },

  { id: "hdt-034", s: "hadith", g: 2, d: 3, t: ["tadlis", "broken-chain"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on tadlīs",
    en: ["What is tadlīs al-isnād?", ["Narrating, in vague wording, what he did not hear from a teacher he met", "Calling one's teacher by an unfamiliar name in order to hide him", "Narrating a report by its meaning instead of its exact wording", "Narrating from someone's book without that author's permission"], "In tadlīs al-isnād the narrator uses a phrase such as 'from' or 'he said' that suggests hearing, while he actually got it through someone else. Concealing the teacher with an obscure name is tadlīs al-shuyūkh."],
    de: ["Was ist Tadlīs al-Isnād?", ["Von einem getroffenen Lehrer Ungehörtes in mehrdeutiger Form weitergeben", "Dem eigenen Lehrer einen ungewohnten Namen geben, um ihn zu verbergen", "Einen Bericht sinngemäß statt im genauen Wortlaut weitergeben", "Aus einem Buch ohne Erlaubnis des Verfassers überliefern"], "Beim Tadlīs al-Isnād verwendet der Überlieferer eine Wendung wie „von“ oder „er sagte“, die ein Hören nahelegt, obwohl er es über einen anderen erhielt. Das Verbergen des Lehrers durch einen unbekannten Namen ist Tadlīs al-Shuyūkh."],
    ar: ["ما تدليس الإسناد؟", ["أن يروي عمن لقيه ما لم يسمعه منه بصيغة محتملة", "أن يسمي شيخه باسم غير معروف ليخفيه عن الناس", "أن يروي الحديث بمعناه دون لفظه الذي سمعه", "أن يروي من كتاب غيره دون إذن من مؤلفه"], "تدليس الإسناد أن يروي الراوي عمن لقيه ما لم يسمعه منه بصيغة توهم السماع كـ«عن» و«قال»، أما تسمية الشيخ بما لا يُعرف به فهو تدليس الشيوخ."] },

  { id: "hdt-035", s: "hadith", g: 2, d: 2, t: ["transmission-methods", "ijaza"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ways of receiving hadith, the ijāza",
    en: ["As a way of receiving hadith, what is ijāza?", ["The teacher's permission to narrate his reports without hearing them", "The student reciting the teacher's reports back to him in a session", "The teacher handing a copy of his book to the student in person", "The student finding the reports written in his teacher's handwriting"], "Ijāza is permission, spoken or written, to narrate the teacher's material. Reciting to the teacher is qirāʾa, handing over the book is munāwala, and finding a handwritten text is wijāda."],
    de: ["Was ist Ijāza als Weg der Hadith-Aufnahme?", ["Die Erlaubnis des Lehrers, seine Berichte ungehört weiterzugeben", "Das Vortragen der Berichte des Lehrers durch den Schüler in einer Sitzung", "Das persönliche Überreichen einer Abschrift des Buches an den Schüler", "Das Auffinden der Berichte in der Handschrift des eigenen Lehrers"], "Ijāza ist die mündliche oder schriftliche Erlaubnis, das Material des Lehrers zu überliefern. Das Vortragen ist Qirāʾa, das Überreichen des Buches Munāwala und das Auffinden einer Handschrift Wijāda."],
    ar: ["ما الإجازة من طرق التحمل؟", ["إذن الشيخ في رواية مروياته من غير سماع", "قراءة الطالب المرويات على الشيخ", "دفع الشيخ كتابه إلى الطالب", "عثور الطالب على المرويات بخط الشيخ"], "الإجازة إذن الشيخ لفظًا أو كتابة في رواية مروياته، أما القراءة عليه فعرض، ودفع الكتاب مناولة، والعثور على الخط وجادة."] },

  { id: "hdt-036", s: "hadith", g: 2, d: 2, t: ["transmission-methods", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ways of receiving hadith, qirāʾa",
    en: ["Reading hadith to the teacher while he listens and confirms is also called:", ["ʿArḍ", "Wijāda", "Iʿlām", "Waṣiyya"], "Qirāʾa ʿalā al-shaykh is also called ʿarḍ ('presentation'), because the student presents the material to the teacher. Wijāda, iʿlām and waṣiyya are weaker, separate methods."],
    de: ["Das Vorlesen von Hadithen vor dem Lehrer, während er zuhört und bestätigt, heißt auch:", ["ʿArḍ", "Wijāda", "Iʿlām", "Waṣiyya"], "Qirāʾa ʿalā al-Shaykh heißt auch ʿArḍ („Vorlage“), weil der Schüler dem Lehrer das Material vorlegt. Wijāda, Iʿlām und Waṣiyya sind schwächere, eigene Wege."],
    ar: ["القراءة على الشيخ وهو يسمع ويقر تسمى أيضًا:", ["العرض", "الوجادة", "الإعلام", "الوصية"], "القراءة على الشيخ تسمى العرض لأن الطالب يعرض ما يقرؤه على الشيخ، وأما الوجادة والإعلام والوصية فطرق مستقلة أضعف منها."] },

  { id: "hdt-037", s: "hadith", g: 2, d: 2, t: ["key-works", "muqaddima-ibn-al-salah"], src: "Ibn al-Ṣalāḥ, Muqaddima, introduction",
    en: ["Besides 'the Muqaddima', by what title is Ibn al-Ṣalāḥ's work on hadith terminology known?", ["ʿUlūm al-Ḥadīth", "Nuzhat al-Naẓar", "al-Kifāya fī ʿIlm al-Riwāya", "Tadrīb al-Rāwī"], "Ibn al-Ṣalāḥ's work is known as ʿUlūm al-Ḥadīth (also Maʿrifat Anwāʿ ʿIlm al-Ḥadīth). Nuzhat al-Naẓar is by Ibn Ḥajar, al-Kifāya by al-Khaṭīb al-Baghdādī and Tadrīb al-Rāwī by al-Suyūṭī."],
    de: ["Unter welchem Titel ist Ibn al-Ṣalāḥs Werk zur Hadith-Terminologie neben „die Muqaddima“ bekannt?", ["ʿUlūm al-Ḥadīth", "Nuzhat al-Naẓar", "al-Kifāya fī ʿIlm al-Riwāya", "Tadrīb al-Rāwī"], "Ibn al-Ṣalāḥs Werk ist als ʿUlūm al-Ḥadīth (auch Maʿrifat Anwāʿ ʿIlm al-Ḥadīth) bekannt. Nuzhat al-Naẓar stammt von Ibn Ḥajar, al-Kifāya von al-Khaṭīb al-Baghdādī und Tadrīb al-Rāwī von al-Suyūṭī."],
    ar: ["بأي اسم يُعرف كتاب ابن الصلاح في المصطلح إلى جانب «المقدمة»؟", ["علوم الحديث", "نزهة النظر", "الكفاية في علم الرواية", "تدريب الراوي"], "كتاب ابن الصلاح يعرف بعلوم الحديث أو معرفة أنواع علم الحديث، أما نزهة النظر فلابن حجر، والكفاية للخطيب البغدادي، وتدريب الراوي للسيوطي."] },

  { id: "hdt-038", s: "hadith", g: 2, d: 3, t: ["fabrication", "narration-ethics"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the mawḍūʿ",
    en: ["What is the ruling on narrating a hadith known to be fabricated?", ["Forbidden, except when stating that it is fabricated", "Allowed in sermons if the meaning is good", "Allowed for virtuous deeds but not for rulings", "Allowed if the narrator gives the full chain"], "Ibn al-Ṣalāḥ states that narrating a fabricated report knowingly is not permitted in any subject unless its fabrication is made clear. Unlike some weak reports, it has no place even in virtues and exhortation."],
    de: ["Wie ist die Bestimmung zur Weitergabe eines Hadith, von dem man weiß, dass er erfunden ist?", ["Verboten, außer man stellt klar, dass er erfunden ist", "In Predigten erlaubt, wenn die Bedeutung gut ist", "Für Tugendwerke erlaubt, nicht aber für Bestimmungen", "Erlaubt, wenn der Überlieferer die volle Kette nennt"], "Ibn al-Ṣalāḥ stellt fest, dass die wissentliche Weitergabe eines erfundenen Berichts in keinem Bereich erlaubt ist, es sei denn, die Erfindung wird klargestellt. Anders als manche schwachen Berichte hat er selbst bei Tugenden und Ermahnung keinen Platz."],
    ar: ["ما حكم رواية الحديث الموضوع مع العلم بوضعه؟", ["محرمة إلا مع بيان أنه موضوع", "جائزة في الخطب إن كان معناه حسنًا", "جائزة في الفضائل دون الأحكام", "جائزة إذا ذكر الراوي الإسناد كاملًا"], "قرر ابن الصلاح أنه لا تحل رواية الموضوع لمن علم حاله في أي معنى كان إلا مقرونًا ببيان وضعه، فلا يدخل في الفضائل والترغيب كما قد يدخل بعض الضعيف."] },

  { id: "hdt-039", s: "hadith", g: 2, d: 3, t: ["hadith-qudsi", "quran-distinction"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, on the difference between the Quran and the ḥadīth qudsī",
    en: ["Which feature belongs to the Quran but not to the ḥadīth qudsī?", ["Its recitation is worship and valid in the prayer", "It is attributed to Allah as its ultimate source", "It was conveyed to the people by the Prophet", "It contains guidance, promises and exhortation"], "Both are attributed to Allah and conveyed by the Prophet, and both contain guidance. Only the Quran is recited in the prayer as worship and is inimitable in its wording."],
    de: ["Welches Merkmal gehört zum Koran, nicht aber zum Ḥadīth Qudsī?", ["Seine Rezitation ist Gottesdienst und im Gebet gültig", "Er wird Allah als letztem Ursprung zugeschrieben", "Er wurde den Menschen vom Propheten übermittelt", "Er enthält Rechtleitung, Verheißung und Ermahnung"], "Beide werden Allah zugeschrieben, vom Propheten übermittelt und enthalten Rechtleitung. Nur der Koran wird im Gebet als Gottesdienst rezitiert und ist in seinem Wortlaut unnachahmlich."],
    ar: ["أيّ الصفات تختص بالقرآن دون الحديث القدسي؟", ["التعبد بتلاوته وصحة الصلاة به", "إضافته إلى الله تعالى", "تبليغ النبي صلى الله عليه وسلم له", "اشتماله على الهداية والموعظة"], "يشترك القرآن والحديث القدسي في الإضافة إلى الله وفي تبليغ النبي صلى الله عليه وسلم واشتمالهما على الهداية، ويختص القرآن بالتعبد بتلاوته والصلاة به والإعجاز بلفظه."] },

  { id: "hdt-040", s: "hadith", g: 2, d: 3, t: ["mutawatir-ahad", "epistemology"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, on the mutawātir",
    en: ["Why does Ibn Ḥajar say the mutawātir is not studied in the science of isnād?", ["It yields certainty without examining its narrators", "It is always narrated without any chain of narrators", "All of its narrators at every level are Companions", "It is limited to reports concerning the Quran's text"], "Because tawātur produces necessary knowledge, there is no need to check the narrators' reliability; the isnād sciences examine reports to decide acceptance, which is the domain of the āḥād."],
    de: ["Warum gehört das Mutawātir nach Ibn Ḥajar nicht zum Untersuchungsgegenstand der Isnād-Wissenschaft?", ["Es ergibt Gewissheit, ohne dass man die Überlieferer prüft", "Es wird immer ganz ohne Überliefererkette weitergegeben", "Alle seine Überlieferer auf jeder Stufe sind Gefährten", "Es beschränkt sich auf Berichte über den Text des Korans"], "Weil Tawātur notwendiges Wissen bewirkt, muss die Zuverlässigkeit der Überlieferer nicht geprüft werden; die Isnād-Wissenschaften prüfen Berichte zur Entscheidung über ihre Annahme, und das betrifft die Āḥād."],
    ar: ["لماذا قال ابن حجر إن المتواتر ليس من مباحث علم الإسناد؟", ["لأنه يفيد العلم دون بحث عن أحوال رواته", "لأنه يروى دائمًا من غير إسناد أصلًا", "لأن رواته في كل طبقة من الصحابة", "لأنه مقصور على ما يتعلق بنص القرآن"], "المتواتر يفيد العلم الضروري فلا يُبحث عن أحوال رواته، وعلم الإسناد يبحث في صحة الحديث أو ضعفه ليُعمل به أو يُترك، وذلك في الآحاد."] },

  { id: "hdt-041", s: "hadith", g: 2, d: 2, t: ["jarh-tadil", "terminology"], src: "Ibn Abī Ḥātim, al-Jarḥ wa-l-Taʿdīl, introduction",
    en: ["What is the purpose of al-jarḥ wa-l-taʿdīl?", ["Judging narrators as reliable or not, to assess their reports", "Explaining the legal rulings contained in individual hadiths", "Arranging hadiths according to the chapters of fiqh books", "Reconciling hadiths that appear to contradict one another"], "Jarḥ (impugning) and taʿdīl (vouching for) are the critics' judgements on narrators; on them depends whether a chain is accepted. Reconciling apparent contradictions belongs to mukhtalif al-ḥadīth."],
    de: ["Welchem Zweck dient al-Jarḥ wa-l-Taʿdīl?", ["Der Bewertung der Überlieferer als zuverlässig oder nicht", "Der Erklärung der Rechtsbestimmungen in Hadithen", "Der Anordnung der Hadithe nach Kapiteln des Fiqh", "Dem Ausgleich scheinbar widersprüchlicher Hadithe"], "Jarḥ (Bemängelung) und Taʿdīl (Beglaubigung) sind die Urteile der Kritiker über Überlieferer; davon hängt ab, ob eine Kette angenommen wird. Der Ausgleich scheinbarer Widersprüche gehört zu Mukhtalif al-Ḥadīth."],
    ar: ["ما الغاية من علم الجرح والتعديل؟", ["الحكم على الرواة توثيقًا وتضعيفًا", "بيان الأحكام الفقهية في الأحاديث", "ترتيب الأحاديث على أبواب الفقه", "الجمع بين الأحاديث المتعارضة ظاهرًا"], "الجرح والتعديل حكم النقاد على الرواة بالقدح أو التزكية، وعليه يتوقف قبول الإسناد أو رده، أما الجمع بين المتعارض ظاهرًا فمن علم مختلف الحديث."] },

  { id: "hdt-042", s: "hadith", g: 3, d: 3, t: ["mutawatir-ahad", "terminology"], src: "al-Suyūṭī, Tadrīb al-Rāwī, the type on the mashhūr and mutawātir",
    en: ["What is the difference between mutawātir lafẓī and mutawātir maʿnawī?", ["Lafẓī: the wording is mass-transmitted; maʿnawī: only a shared meaning", "Lafẓī: the chain is connected; maʿnawī: the chain has gaps in it", "Lafẓī: it is from the Prophet; maʿnawī: it is from the Companions", "Lafẓī: it yields certainty; maʿnawī: it yields only probability"], "Lafẓī tawātur means the same wording reaches us through mass transmission. Maʿnawī tawātur means many different reports, each perhaps āḥād, share one common meaning, such as the Prophet raising his hands in supplication. Both yield certainty."],
    de: ["Worin unterscheiden sich Mutawātir lafẓī und Mutawātir maʿnawī?", ["Lafẓī: der Wortlaut ist massenhaft überliefert; maʿnawī: nur eine gemeinsame Bedeutung", "Lafẓī: die Kette ist zusammenhängend; maʿnawī: die Kette weist Lücken auf", "Lafẓī: es stammt vom Propheten; maʿnawī: es stammt von den Gefährten", "Lafẓī: es ergibt Gewissheit; maʿnawī: es ergibt nur Wahrscheinlichkeit"], "Lafẓī bedeutet, dass derselbe Wortlaut massenhaft überliefert ist. Maʿnawī bedeutet, dass viele verschiedene, einzeln vielleicht Āḥād-Berichte eine gemeinsame Bedeutung teilen, etwa das Heben der Hände beim Bittgebet. Beide ergeben Gewissheit."],
    ar: ["ما الفرق بين المتواتر اللفظي والمتواتر المعنوي؟", ["اللفظي تواتر لفظه، والمعنوي تواتر معنى مشترك", "اللفظي متصل السند، والمعنوي في سنده انقطاع", "اللفظي مرفوع، والمعنوي موقوف على الصحابة", "اللفظي يفيد اليقين، والمعنوي يفيد الظن"], "المتواتر اللفظي ما تواتر لفظه، والمعنوي ما اختلفت ألفاظه ووقائعه واشتركت في معنى واحد تواتر به، كرفع اليدين في الدعاء، وكلاهما يفيد العلم."] },

  { id: "hdt-043", s: "hadith", g: 3, d: 4, t: ["supporting-routes", "terminology"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on al-iʿtibār, al-mutābiʿ and al-shāhid",
    en: ["In Ibn Ḥajar's usage, how does a shāhid differ from a mutābiʿ?", ["A shāhid is via another Companion; a mutābiʿ via the same one", "A shāhid supports the chain; a mutābiʿ supports only the text", "A shāhid must be ṣaḥīḥ; a mutābiʿ may even be fabricated", "A shāhid is always mawqūf; a mutābiʿ is always marfūʿ"], "Ibn Ḥajar calls a supporting route through the same Companion a mutābiʿ and one through another Companion a shāhid, while noting that the terms are sometimes used interchangeably. The search for both is called iʿtibār."],
    de: ["Wie unterscheidet sich nach Ibn Ḥajars Sprachgebrauch ein Shāhid von einem Mutābiʿ?", ["Ein Shāhid kommt über einen anderen Gefährten, ein Mutābiʿ über denselben", "Ein Shāhid stützt die Kette, ein Mutābiʿ dagegen nur den Text", "Ein Shāhid muss ṣaḥīḥ sein, ein Mutābiʿ darf sogar erfunden sein", "Ein Shāhid ist immer mawqūf, ein Mutābiʿ dagegen immer marfūʿ"], "Ibn Ḥajar nennt einen stützenden Weg über denselben Gefährten Mutābiʿ und über einen anderen Gefährten Shāhid, merkt aber an, dass die Begriffe teils austauschbar verwendet werden. Die Suche nach beiden heißt Iʿtibār."],
    ar: ["بم يفترق الشاهد عن المتابع في اصطلاح ابن حجر؟", ["الشاهد من حديث صحابي آخر، والمتابع من حديث الصحابي نفسه", "الشاهد يقوي الإسناد، والمتابع لا يقوي إلا المتن", "الشاهد يشترط صحته، والمتابع يجوز أن يكون موضوعًا", "الشاهد موقوف دائمًا، والمتابع مرفوع في كل حال"], "المتابع عند ابن حجر ما شارك فيه الراوي غيره من حديث الصحابي نفسه، والشاهد ما جاء من حديث صحابي آخر، وقد يطلق كل منهما على الآخر، وتتبع الطرق لذلك هو الاعتبار."] },

  { id: "hdt-044", s: "hadith", g: 3, d: 3, t: ["contradiction", "shadhdh"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the shādhdh and the munkar",
    en: ["What is the term for the preferred report that stands against a munkar one?", ["Maʿrūf", "Maḥfūẓ", "Muḥkam", "Mutābiʿ"], "In Ibn Ḥajar's pairs, the preferred report against a shādhdh is maḥfūẓ, and the preferred report against a munkar is maʿrūf. Muḥkam refers to a report free of any opposing report."],
    de: ["Wie heißt der bevorzugte Bericht, der einem Munkar-Bericht gegenübersteht?", ["Maʿrūf", "Maḥfūẓ", "Muḥkam", "Mutābiʿ"], "In Ibn Ḥajars Begriffspaaren heißt der bevorzugte Bericht gegenüber dem Shādhdh maḥfūẓ und gegenüber dem Munkar maʿrūf. Muḥkam bezeichnet einen Bericht ohne jeden Gegenbericht."],
    ar: ["ما اسم الراجح المقابل للمنكر؟", ["المعروف", "المحفوظ", "المحكم", "المتابع"], "في اصطلاح ابن حجر يقابل الشاذَّ المحفوظُ، ويقابل المنكرَ المعروفُ، أما المحكم فهو الحديث المقبول السالم من المعارضة."] },

  { id: "hdt-045", s: "hadith", g: 3, d: 4, t: ["tadlis", "broken-chain"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the mudallas and the mursal khafī",
    en: ["According to Ibn Ḥajar, what separates tadlīs from mursal khafī?", ["Tadlīs: from one he met; mursal khafī: from a contemporary never met", "Tadlīs drops a Companion; mursal khafī drops a Successor from the chain", "Tadlīs occurs in the text; mursal khafī occurs only in the chain", "Tadlīs is deliberate lying; mursal khafī is an innocent slip of memory"], "Both use an ambiguous phrase suggesting hearing. Ibn Ḥajar distinguishes them by the relationship: if the narrator is known to have met the teacher it is tadlīs; if he was only his contemporary without meeting it is mursal khafī."],
    de: ["Was trennt nach Ibn Ḥajar Tadlīs vom Mursal Khafī?", ["Tadlīs: von einem Getroffenen; Mursal Khafī: von einem nie getroffenen Zeitgenossen", "Tadlīs lässt einen Gefährten weg, Mursal Khafī einen Nachfolger aus der Kette", "Tadlīs kommt im Text vor, Mursal Khafī dagegen nur in der Überliefererkette", "Tadlīs ist bewusste Lüge, Mursal Khafī dagegen ein harmloser Gedächtnisfehler"], "Beide verwenden eine mehrdeutige Wendung, die ein Hören nahelegt. Ibn Ḥajar unterscheidet nach der Beziehung: Ist eine Begegnung mit dem Lehrer bekannt, ist es Tadlīs; war er nur Zeitgenosse ohne Begegnung, ist es Mursal Khafī."],
    ar: ["بم يفرق ابن حجر بين التدليس والمرسل الخفي؟", ["التدليس عمن لقيه، والمرسل الخفي عمن عاصره ولم يلقه", "التدليس بإسقاط صحابي، والمرسل الخفي بإسقاط تابعي", "التدليس في المتن، والمرسل الخفي في السند", "التدليس كذب متعمد، والمرسل الخفي خطأ في الحفظ"], "كلاهما بصيغة محتملة توهم السماع، وفرق ابن حجر بينهما بأن التدليس يختص بمن روى عمن عُرف لقاؤه إياه، فإن عاصره ولم يُعرف أنه لقيه فهو المرسل الخفي."] },

  { id: "hdt-046", s: "hadith", g: 3, d: 3, t: ["tadlis", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on tadlīs",
    en: ["A narrator refers to his teacher by an unfamiliar name, kunya or attribution so that the teacher is not recognised. This is called:", ["Tadlīs al-shuyūkh", "Tadlīs al-isnād", "Tadlīs al-taswiya", "Irsāl khafī"], "In tadlīs al-shuyūkh nothing is dropped from the chain; the teacher is disguised by an unusual description. Its harm is that it makes the teacher hard to identify and evaluate."],
    de: ["Ein Überlieferer bezeichnet seinen Lehrer mit einem ungewohnten Namen, einer Kunya oder Herkunftsangabe, damit man ihn nicht erkennt. Das heißt:", ["Tadlīs al-Shuyūkh", "Tadlīs al-Isnād", "Tadlīs al-Taswiya", "Irsāl Khafī"], "Beim Tadlīs al-Shuyūkh fällt nichts aus der Kette; der Lehrer wird durch eine ungewöhnliche Bezeichnung verschleiert. Der Schaden liegt darin, dass der Lehrer schwer zu identifizieren und zu beurteilen ist."],
    ar: ["أن يسمي الراوي شيخه أو يكنيه أو ينسبه بما لا يُعرف به كي لا يُعرف، يسمى:", ["تدليس الشيوخ", "تدليس الإسناد", "تدليس التسوية", "الإرسال الخفي"], "في تدليس الشيوخ لا يسقط أحد من الإسناد، وإنما يُعمَّى الشيخ بوصف غير مشهور، فيصعب تعيينه ومعرفة حاله."] },

  { id: "hdt-047", s: "hadith", g: 3, d: 4, t: ["jarh-tadil", "unknown-narrator"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on jahāla",
    en: ["In Ibn Ḥajar's terms, what is majhūl al-ʿayn?", ["A named narrator with only one person narrating from him, unvouched", "A narrator from whom two narrate but whose reliability is unestablished", "A narrator who is not mentioned by name anywhere in the chain", "A narrator whose name is known but whose date of death is unknown"], "Majhūl al-ʿayn has a single narrator from him and no vouching. If two or more narrate from him without vouching, he is majhūl al-ḥāl (mastūr). An unnamed narrator is called mubham."],
    de: ["Was ist nach Ibn Ḥajar ein Majhūl al-ʿAyn?", ["Ein namentlich genannter Überlieferer, von dem nur einer überliefert und den niemand beglaubigt", "Ein Überlieferer, von dem zwei überliefern, dessen Zuverlässigkeit aber nicht feststeht", "Ein Überlieferer, der in der Kette überhaupt nicht genannt wird", "Ein Überlieferer, dessen Name bekannt, dessen Todesdatum aber unbekannt ist"], "Beim Majhūl al-ʿAyn überliefert nur einer von ihm, und niemand beglaubigt ihn. Überliefern zwei oder mehr ohne Beglaubigung, ist er Majhūl al-Ḥāl (Mastūr). Ein ungenannter Überlieferer heißt Mubham."],
    ar: ["من مجهول العين في اصطلاح ابن حجر؟", ["من سُمّي ولم يرو عنه إلا واحد ولم يوثق", "من روى عنه اثنان فأكثر ولم تثبت عدالته", "من لم يُسمَّ في الإسناد أصلًا", "من عُرف اسمه وجُهلت سنة وفاته"], "مجهول العين من سمي وانفرد عنه راوٍ واحد ولم يوثق، فإن روى عنه اثنان فصاعدًا ولم يوثق فهو مجهول الحال أو المستور، ومن لم يُسمَّ فهو المبهم."] },

  { id: "hdt-048", s: "hadith", g: 3, d: 4, t: ["jarh-tadil", "explained-criticism"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on who is accepted as a narrator",
    en: ["What position does Ibn al-Ṣalāḥ state as correct regarding the reasons for jarḥ and taʿdīl?", ["Taʿdīl is accepted without a reason; jarḥ only with its cause", "Both are accepted only when their causes are clearly explained", "Jarḥ is accepted without a reason; taʿdīl only with its cause", "Neither needs a stated reason if the critic is a known imam"], "Ibn al-Ṣalāḥ reasons that the causes of uprightness are many and hard to list, while people differ over what counts as a defect; so jarḥ needs explanation (mufassar), but taʿdīl does not."],
    de: ["Welche Ansicht bezeichnet Ibn al-Ṣalāḥ als richtig hinsichtlich der Gründe für Jarḥ und Taʿdīl?", ["Taʿdīl wird ohne Begründung angenommen, Jarḥ nur mit erklärter Ursache", "Beide werden nur mit erklärter Ursache angenommen", "Jarḥ wird ohne Begründung angenommen, Taʿdīl nur mit Erklärung", "Keines braucht eine Begründung, wenn der Kritiker ein bekannter Imam ist"], "Ibn al-Ṣalāḥ begründet: Die Ursachen der Rechtschaffenheit sind zahlreich und schwer aufzuzählen, während die Menschen uneins sind, was als Mangel gilt; daher braucht Jarḥ eine Erklärung (mufassar), Taʿdīl nicht."],
    ar: ["ما القول الذي صححه ابن الصلاح في ذكر سبب الجرح والتعديل؟", ["يقبل التعديل مبهمًا، ولا يقبل الجرح إلا مفسرًا", "لا يقبل الجرح ولا التعديل إلا مفسرين", "يقبل الجرح مبهمًا، ولا يقبل التعديل إلا مفسرًا", "لا يحتاج أحدهما إلى سبب إذا كان الناقد إمامًا"], "علل ابن الصلاح ذلك بأن أسباب العدالة كثيرة يشق ذكرها، وأما الجرح فيختلف الناس فيما يجرح به، فلا يقبل إلا مفسرًا مبين السبب."] },

  { id: "hdt-049", s: "hadith", g: 3, d: 3, t: ["jarh-tadil", "grading-expressions"], src: "Ibn Abī Ḥātim, al-Jarḥ wa-l-Taʿdīl, introduction on the levels of narrators",
    en: ["Which expression of taʿdīl indicates the highest level of reliability among these?", ["Thiqa thabt", "Ṣadūq", "Lā baʾsa bihi", "Shaykh"], "Repeating or combining words of firm reliability, as in 'thiqa thabt', ranks above a single term. Ṣadūq and lā baʾsa bihi indicate a lower level, and shaykh lower still."],
    de: ["Welcher Ausdruck des Taʿdīl bezeichnet unter diesen die höchste Stufe der Zuverlässigkeit?", ["Thiqa thabt", "Ṣadūq", "Lā baʾsa bihi", "Shaykh"], "Die Wiederholung oder Verbindung von Wörtern fester Zuverlässigkeit wie „thiqa thabt“ steht über einem einzelnen Begriff. Ṣadūq und lā baʾsa bihi bezeichnen eine niedrigere Stufe, shaykh eine noch niedrigere."],
    ar: ["أي ألفاظ التعديل التالية أعلى مرتبة؟", ["ثقة ثبت", "صدوق", "لا بأس به", "شيخ"], "تكرار لفظ التوثيق أو الجمع بين لفظين منه كقولهم ثقة ثبت أرفع من اللفظ المفرد، وصدوق ولا بأس به دونه، وشيخ أدنى منهما."] },

  { id: "hdt-050", s: "hadith", g: 3, d: 3, t: ["jarh-tadil", "grading-expressions"], src: "al-Sakhāwī, Fatḥ al-Mughīth, on the levels of jarḥ",
    en: ["Which of these expressions represents the most severe level of jarḥ?", ["Kadhdhāb", "Layyin al-ḥadīth", "Fīhi maqāl", "Ḍaʿīf"], "Describing a narrator as a liar (kadhdhāb) or fabricator is the gravest jarḥ, and his reports are not used even as support. Layyin and fīhi maqāl are among the lightest expressions of weakness."],
    de: ["Welcher dieser Ausdrücke stellt die schwerste Stufe des Jarḥ dar?", ["Kadhdhāb", "Layyin al-ḥadīth", "Fīhi maqāl", "Ḍaʿīf"], "Die Bezeichnung als Lügner (kadhdhāb) oder Fälscher ist der schwerste Jarḥ; seine Berichte dienen nicht einmal zur Stützung. Layyin und fīhi maqāl gehören zu den leichtesten Ausdrücken der Schwäche."],
    ar: ["أي ألفاظ الجرح التالية أشد مرتبة؟", ["كذاب", "لين الحديث", "فيه مقال", "ضعيف"], "وصف الراوي بالكذب أو الوضع أشد مراتب الجرح، فلا يُعتبر بحديثه ولا يُستشهد به، وأما لين الحديث وفيه مقال فمن أخف مراتب التجريح."] },

  { id: "hdt-051", s: "hadith", g: 3, d: 3, t: ["transmission-methods", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ways of receiving hadith",
    en: ["Which of the following is NOT among the eight ways of receiving hadith listed by Ibn al-Ṣalāḥ?", ["Istifāḍa", "Munāwala", "Waṣiyya", "Iʿlām"], "Ibn al-Ṣalāḥ lists samāʿ, qirāʾa, ijāza, munāwala, kitāba, iʿlām, waṣiyya and wijāda. Istifāḍa (widespread report) is a term from the law of testimony, not a way of receiving hadith."],
    de: ["Welcher der folgenden gehört NICHT zu den acht Wegen der Hadith-Aufnahme bei Ibn al-Ṣalāḥ?", ["Istifāḍa", "Munāwala", "Waṣiyya", "Iʿlām"], "Ibn al-Ṣalāḥ nennt Samāʿ, Qirāʾa, Ijāza, Munāwala, Kitāba, Iʿlām, Waṣiyya und Wijāda. Istifāḍa (weite Verbreitung) ist ein Begriff aus dem Zeugenrecht, kein Weg der Hadith-Aufnahme."],
    ar: ["أيّ مما يلي ليس من طرق التحمل الثمانية عند ابن الصلاح؟", ["الاستفاضة", "المناولة", "الوصية", "الإعلام"], "طرق التحمل عند ابن الصلاح: السماع، والقراءة، والإجازة، والمناولة، والكتابة، والإعلام، والوصية، والوجادة، وأما الاستفاضة فمن مصطلحات باب الشهادات."] },

  { id: "hdt-052", s: "hadith", g: 3, d: 3, t: ["transmission-methods", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ways of receiving hadith, wijāda",
    en: ["What is wijāda?", ["Finding reports in someone's handwriting, without hearing or permission", "Hearing reports from a teacher together with many others in a large gathering", "Receiving a teacher's books because he bequeathed them in his will", "Receiving a letter from a teacher containing reports written for him"], "Wijāda is coming across a text in the known handwriting of a narrator without having heard it from him or received permission. One may say 'I found in the handwriting of so-and-so', but not 'he narrated to me'."],
    de: ["Was ist Wijāda?", ["Das Auffinden von Berichten in jemandes Handschrift ohne Hören oder Erlaubnis", "Das Hören von Berichten bei einem Lehrer zusammen mit vielen in großer Versammlung", "Der Erhalt der Bücher eines Lehrers, weil er sie testamentarisch vermacht hat", "Der Erhalt eines Briefes vom Lehrer mit Berichten, die er eigens niederschrieb"], "Wijāda bedeutet, einen Text in der bekannten Handschrift eines Überlieferers zu finden, ohne ihn von ihm gehört oder eine Erlaubnis erhalten zu haben. Man darf sagen „ich fand in der Handschrift von …“, nicht aber „er überlieferte mir“."],
    ar: ["ما الوجادة؟", ["أن يجد أحاديث بخط راوٍ من غير سماع ولا إجازة", "أن يسمع من الشيخ مع جمع كثير في مجلس عام", "أن يوصي الشيخ بكتبه للطالب عند موته", "أن يكتب الشيخ إلى الطالب بأحاديث يرسلها إليه"], "الوجادة أن يقف على أحاديث بخط راوٍ يعرف خطه ولم يسمعها منه ولم يُجز له، فيقول: وجدت بخط فلان، ولا يقول: حدثني."] },

  { id: "hdt-053", s: "hadith", g: 3, d: 3, t: ["transmission-methods", "ijaza"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ways of receiving hadith, munāwala",
    en: ["Which form of munāwala does Ibn al-Ṣalāḥ treat as the highest?", ["Handing over the book together with permission to narrate it", "Handing over the book to the student without any permission", "Giving permission to narrate without handing over anything", "Sending the book in writing to a student in another city"], "The highest munāwala is when the teacher gives the student his original or a checked copy and says it is his narration and he permits him to narrate it. Munāwala without permission is weak according to the sound view."],
    de: ["Welche Form der Munāwala betrachtet Ibn al-Ṣalāḥ als die höchste?", ["Das Überreichen des Buches zusammen mit der Erlaubnis zur Überlieferung", "Das Überreichen des Buches an den Schüler ganz ohne jede Erlaubnis", "Die Erlaubnis zur Überlieferung, ohne irgendetwas zu überreichen", "Das schriftliche Zusenden des Buches an einen Schüler in einer anderen Stadt"], "Die höchste Munāwala liegt vor, wenn der Lehrer dem Schüler sein Original oder eine geprüfte Abschrift gibt, sagt, dies sei seine Überlieferung, und ihm die Weitergabe erlaubt. Munāwala ohne Erlaubnis ist nach der richtigen Ansicht schwach."],
    ar: ["أي صور المناولة جعلها ابن الصلاح أعلاها؟", ["المناولة المقرونة بالإجازة", "المناولة المجردة عن الإجازة", "الإجازة المجردة عن المناولة", "إرسال الكتاب مكاتبة إلى بلد آخر"], "أعلى المناولة أن يدفع الشيخ إلى الطالب أصل سماعه أو فرعًا مقابلًا به ويقول: هذا سماعي فاروه عني، وأما المناولة المجردة عن الإجازة فلا تجوز الرواية بها على الصحيح."] },

  { id: "hdt-054", s: "hadith", g: 3, d: 4, t: ["contradiction", "mudtarib"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the muḍṭarib",
    en: ["When is a hadith called muḍṭarib?", ["When its versions conflict, are equally strong, and none can be preferred", "When a weak narrator in it contradicts one or more reliable narrators", "When one of its versions is clearly stronger than all the other versions", "When a narrator adds his own explanation into the text of the report"], "Iḍṭirāb requires conflicting versions of comparable strength with no way to reconcile or prefer. If one version is stronger, it is preferred and the hadith is not called muḍṭarib."],
    de: ["Wann heißt ein Hadith muḍṭarib?", ["Wenn seine Fassungen sich widersprechen, gleich stark sind und keine vorzuziehen ist", "Wenn ein schwacher Überlieferer darin einem oder mehreren zuverlässigen widerspricht", "Wenn eine seiner Fassungen deutlich stärker ist als alle anderen Fassungen", "Wenn ein Überlieferer seine eigene Erklärung in den Text des Berichts einfügt"], "Iḍṭirāb verlangt widersprüchliche Fassungen vergleichbarer Stärke ohne Möglichkeit des Ausgleichs oder der Bevorzugung. Ist eine Fassung stärker, wird sie bevorzugt, und der Hadith heißt nicht muḍṭarib."],
    ar: ["متى يسمى الحديث مضطربًا؟", ["إذا اختلفت رواياته وتساوت فلم يمكن الترجيح", "إذا خالف فيه راوٍ ضعيف ثقة أو أكثر", "إذا كانت إحدى رواياته أرجح من سائرها بوضوح", "إذا أدخل الراوي تفسيره في متن الحديث"], "المضطرب ما روي على أوجه مختلفة متساوية في القوة لا يمكن الجمع بينها ولا الترجيح، فإن ترجحت إحداها فالحكم للراجح ولا يسمى مضطربًا."] },

  { id: "hdt-055", s: "hadith", g: 3, d: 3, t: ["insertion", "terminology"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the mudraj",
    en: ["A narrator's own words are joined to the Prophet's words without a separating marker. This is called:", ["Mudraj al-matn", "Maqlūb al-matn", "Muṣaḥḥaf", "Mudallas"], "Idrāj in the text means words of a narrator are inserted so that they appear to be part of the hadith, often as an explanation. Maqlūb is an inversion of words or names; muṣaḥḥaf is a change of dots or letters."],
    de: ["Die eigenen Worte eines Überlieferers werden ohne Trennung mit den Worten des Propheten verbunden. Das heißt:", ["Mudraj al-Matn", "Maqlūb al-Matn", "Muṣaḥḥaf", "Mudallas"], "Idrāj im Text bedeutet, dass Worte eines Überlieferers eingefügt werden, sodass sie wie Teil des Hadith wirken, oft als Erklärung. Maqlūb ist eine Vertauschung von Wörtern oder Namen; Muṣaḥḥaf eine Veränderung von Punkten oder Buchstaben."],
    ar: ["أن يدخل في كلام النبي صلى الله عليه وسلم شيء من كلام بعض الرواة دون فصل، يسمى:", ["مدرج المتن", "مقلوب المتن", "المصحف", "المدلس"], "الإدراج في المتن أن يُدخل الراوي في الحديث شيئًا من كلامه تفسيرًا أو غيره فيُتوهم أنه منه، أما القلب فتقديم وتأخير في لفظ أو اسم، والتصحيف تغيير النقط أو الحروف."] },

  { id: "hdt-056", s: "hadith", g: 3, d: 4, t: ["companions", "terminology"], src: "Ibn Ḥajar, al-Iṣāba fī Tamyīz al-Ṣaḥāba, introduction",
    en: ["Someone met the Prophet as a believer, then apostatised, then returned to Islam and died a Muslim. According to the view Ibn Ḥajar calls soundest, is he a Companion?", ["Yes, he is counted a Companion", "No, apostasy cancels companionship permanently", "Only if he met the Prophet again after returning", "Only if he narrated hadith before apostatising"], "Ibn Ḥajar's definition adds that the person counts as a Companion 'even if apostasy intervened, according to the soundest view', provided he died in Islam. Some scholars made renewed meeting a condition, which is why the issue is discussed."],
    de: ["Jemand begegnete dem Propheten als Gläubiger, fiel dann vom Islam ab, kehrte zurück und starb als Muslim. Ist er nach der von Ibn Ḥajar als richtigste bezeichneten Ansicht ein Gefährte?", ["Ja, er zählt als Gefährte", "Nein, der Abfall hebt die Gefährtenschaft dauerhaft auf", "Nur wenn er den Propheten nach der Rückkehr erneut traf", "Nur wenn er vor dem Abfall Hadithe überliefert hatte"], "Ibn Ḥajars Definition fügt hinzu, dass jemand als Gefährte zählt, „auch wenn ein Abfall dazwischenkam, nach der richtigsten Ansicht“, sofern er im Islam starb. Manche Gelehrte machten eine erneute Begegnung zur Bedingung, weshalb die Frage erörtert wird."],
    ar: ["من لقي النبي صلى الله عليه وسلم مؤمنًا ثم ارتد ثم عاد إلى الإسلام ومات عليه، هل هو صحابي على ما صححه ابن حجر؟", ["نعم، يعد صحابيًا", "لا، لأن الردة تبطل الصحبة مطلقًا", "فقط إن لقي النبي صلى الله عليه وسلم بعد عودته", "فقط إن روى الحديث قبل ردته"], "زاد ابن حجر في تعريف الصحابي: ولو تخللت ردة في الأصح، بشرط موته على الإسلام، ومن العلماء من اشترط لقاءه مرة أخرى بعد الإسلام، ولذلك ذُكرت المسألة."] },

  { id: "hdt-057", s: "hadith", g: 3, d: 4, t: ["mursal", "companions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the mursal",
    en: ["How does the majority treat the mursal of a Companion, such as a young Companion reporting an event he did not witness?", ["As connected proof, since the omitted narrator is presumed a Companion", "As weak in the same way as any other mursal from a Successor", "As fabricated unless some Successor independently confirms it", "As mawqūf on that Companion and not attributed to the Prophet"], "Ibn al-Ṣalāḥ notes that the mursal of a Companion is treated as connected, because Companions mostly narrate from other Companions, and all Companions are upright. So the gap does not harm the report."],
    de: ["Wie behandelt die Mehrheit das Mursal eines Gefährten, etwa wenn ein junger Gefährte ein nicht selbst erlebtes Ereignis berichtet?", ["Als zusammenhängend und beweiskräftig, da der Ausgelassene als Gefährte gilt", "Als schwach in gleicher Weise wie jedes andere Mursal eines Nachfolgers", "Als erfunden, solange nicht ein Nachfolger es unabhängig davon bestätigt", "Als mawqūf bei diesem Gefährten und nicht dem Propheten zugeschrieben"], "Ibn al-Ṣalāḥ stellt fest, dass das Mursal eines Gefährten als zusammenhängend gilt, weil Gefährten meist von anderen Gefährten überliefern und alle Gefährten rechtschaffen sind. Die Lücke schadet dem Bericht daher nicht."],
    ar: ["كيف يعامل الجمهور مرسل الصحابي، كأن يروي صحابي صغير واقعة لم يشهدها؟", ["متصلًا يحتج به لأن الساقط صحابي غالبًا", "ضعيفًا كسائر مراسيل التابعين ولا فرق", "موضوعًا ما لم يؤكده تابعي من طريق آخر", "موقوفًا على ذلك الصحابي غير مرفوع"], "ذكر ابن الصلاح أن مرسل الصحابي في حكم الموصول، لأن الصحابة يروون غالبًا عن الصحابة، وكلهم عدول، فلا تضر الجهالة بالساقط."] },

  { id: "hdt-058", s: "hadith", g: 3, d: 4, t: ["transmission-methods", "narrator-conditions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the age and condition for receiving hadith",
    en: ["Jubayr ibn Muṭʿim heard the Prophet recite Sūrat al-Ṭūr in the Maghrib prayer before he became Muslim, and narrated it afterwards. What principle does this illustrate?", ["Receiving as a non-Muslim is valid if one narrates after Islam", "A non-Muslim's narration is accepted without any conditions at all", "Only what is heard after accepting Islam may ever be narrated", "A narrator must be an adult both when hearing and when narrating"], "Scholars distinguish taḥammul (receiving) from adāʾ (conveying). Islam and maturity are conditions for conveying, not for receiving, so what Jubayr heard as a non-Muslim was accepted when he narrated it as a Muslim."],
    de: ["Jubayr ibn Muṭʿim hörte den Propheten im Maghrib-Gebet die Sure al-Ṭūr rezitieren, bevor er Muslim wurde, und überlieferte es danach. Welchen Grundsatz zeigt das?", ["Die Aufnahme als Nichtmuslim gilt, wenn man nach dem Übertritt überliefert", "Die Überlieferung eines Nichtmuslims wird ohne Bedingungen angenommen", "Nur nach dem Übertritt Gehörtes darf je überliefert werden", "Ein Überlieferer muss beim Hören und Weitergeben volljährig sein"], "Die Gelehrten unterscheiden Taḥammul (Aufnahme) und Adāʾ (Weitergabe). Islam und Volljährigkeit sind Bedingungen der Weitergabe, nicht der Aufnahme; daher wurde angenommen, was Jubayr als Nichtmuslim hörte und als Muslim weitergab."],
    ar: ["سمع جبير بن مطعم النبي صلى الله عليه وسلم يقرأ في المغرب بسورة الطور قبل إسلامه ثم رواه بعده، فما القاعدة التي يدل عليها ذلك؟", ["يصح التحمل حال الكفر إذا أدى بعد الإسلام", "تقبل رواية الكافر من غير أي شرط", "لا يروى إلا ما سُمع بعد الدخول في الإسلام", "يشترط البلوغ عند التحمل وعند الأداء معًا"], "فرق العلماء بين التحمل والأداء، فالإسلام والبلوغ شرطان في الأداء لا في التحمل، ولذلك قُبل ما سمعه جبير قبل إسلامه لما أداه بعد إسلامه."] },

  { id: "hdt-059", s: "hadith", g: 4, d: 5, t: ["mursal", "comparative-views"], tr: ["comparative", "hanafi", "maliki", "shafii"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the mursal; al-Shāfiʿī, al-Risāla, on the mursal",
    en: ["Which statement correctly describes the classical positions on using the mursal as proof?", ["Most critics: weak; Mālik and Abū Ḥanīfa: accepted; al-Shāfiʿī: accepted if supported", "Most critics: accepted; Mālik: rejected; al-Shāfiʿī: accepted without any conditions", "All four imams: rejected; only later Ḥanafīs accepted it with conditions", "Al-Shāfiʿī: every mursal accepted; Mālik and Abū Ḥanīfa: rejected entirely"], "Ibn al-Ṣalāḥ reports that the hadith critics settled on its weakness, while acceptance is the position of Mālik, Abū Ḥanīfa and their followers. Al-Shāfiʿī in al-Risāla accepts the mursal of senior Successors when supported, for example by a connected route or another mursal."],
    de: ["Welche Aussage beschreibt die klassischen Positionen zur Beweiskraft des Mursal richtig?", ["Meiste Kritiker: schwach; Mālik und Abū Ḥanīfa: angenommen; al-Shāfiʿī: angenommen, wenn gestützt", "Meiste Kritiker: angenommen; Mālik: abgelehnt; al-Shāfiʿī: angenommen ohne jede Bedingung", "Alle vier Imame: abgelehnt; erst spätere Ḥanafiten nahmen es mit Bedingungen an", "Al-Shāfiʿī: jedes Mursal angenommen; Mālik und Abū Ḥanīfa: gänzlich abgelehnt"], "Ibn al-Ṣalāḥ berichtet, dass sich die Hadith-Kritiker auf seine Schwäche festlegten, während die Annahme die Position Māliks, Abū Ḥanīfas und ihrer Anhänger ist. Al-Shāfiʿī nimmt in al-Risāla das Mursal älterer Nachfolger an, wenn es gestützt wird, etwa durch einen zusammenhängenden Weg oder ein anderes Mursal."],
    ar: ["أي العبارات تصف المذاهب المشهورة في الاحتجاج بالمرسل وصفًا صحيحًا؟", ["جمهور النقاد يضعفونه، ويحتج به مالك وأبو حنيفة، ويقبله الشافعي إذا اعتضد", "جمهور النقاد يقبلونه، ويرده مالك، ويقبله الشافعي بلا أي شرط", "رده الأئمة الأربعة جميعًا، وقبله متأخرو الحنفية بشروط معينة", "يقبل الشافعي كل مرسل، ويرده مالك وأبو حنيفة ردًّا مطلقًا"], "ذكر ابن الصلاح أن سقوط الاحتجاج بالمرسل هو ما استقر عليه حفاظ الحديث، وأن الاحتجاج به مذهب مالك وأبي حنيفة وأصحابهما، وأما الشافعي فقبل في الرسالة مرسل كبار التابعين إذا اعتضد بمسند أو مرسل آخر أو نحو ذلك."] },

  { id: "hdt-060", s: "hadith", g: 4, d: 5, t: ["muanan", "comparative-views", "broken-chain"], tr: ["comparative"], src: "Muslim, Ṣaḥīḥ Muslim, Muqaddima; Ibn Ḥajar, Nuzhat al-Naẓar, on the muʿanʿan",
    en: ["Concerning a chain using 'ʿan' between two non-mudallis narrators, which statement describes the well-known difference?", ["Muslim: contemporaneity with possible meeting suffices; al-Bukhārī (reportedly): one proven meeting", "Al-Bukhārī: contemporaneity alone suffices; Muslim: repeated meetings must be proven", "Both: the narrator must state explicit hearing in every report, or it is broken", "Both: every ʿan-chain is rejected unless that report is also mass-transmitted"], "In the introduction to his Ṣaḥīḥ, Muslim argued that contemporaneity with the possibility of meeting suffices for a non-mudallis. The stricter requirement of proven meeting is attributed to al-Bukhārī and his teacher ʿAlī ibn al-Madīnī."],
    de: ["Welche Aussage beschreibt bei einer Kette mit „ʿan“ zwischen zwei Nicht-Mudallis-Überlieferern den bekannten Unterschied?", ["Muslim: Zeitgenossenschaft mit möglicher Begegnung genügt; al-Bukhārī (berichtet): eine nachgewiesene Begegnung", "Al-Bukhārī: Zeitgenossenschaft allein genügt; Muslim: wiederholte Begegnungen müssen nachgewiesen sein", "Beide: in jedem Bericht muss das Hören ausdrücklich angegeben sein, sonst gilt er als unterbrochen", "Beide: jede ʿan-Kette wird abgelehnt, sofern der Bericht nicht zugleich mutawātir ist"], "In der Einleitung seines Ṣaḥīḥ legte Muslim dar, dass Zeitgenossenschaft mit möglicher Begegnung bei einem Nicht-Mudallis genügt. Die strengere Forderung nach nachgewiesener Begegnung wird al-Bukhārī und seinem Lehrer ʿAlī ibn al-Madīnī zugeschrieben."],
    ar: ["في الإسناد المعنعن بين راويين غير مدلسين، أي العبارات تصف الخلاف المشهور؟", ["مسلم: تكفي المعاصرة مع إمكان اللقاء، ويُنسب إلى البخاري اشتراط لقاء ثابت", "البخاري: تكفي المعاصرة وحدها، ومسلم: يشترط ثبوت اللقاء مرارًا", "كلاهما: يشترط التصريح بالسماع في كل حديث وإلا فهو منقطع", "كلاهما: يرد كل معنعن ما لم يكن ذلك الحديث متواترًا"], "قرر مسلم في مقدمة صحيحه الاكتفاء بالمعاصرة مع إمكان اللقاء لغير المدلس، ويُنسب اشتراط ثبوت اللقاء ولو مرة إلى البخاري وشيخه علي بن المديني."] },

  { id: "hdt-061", s: "hadith", g: 4, d: 4, t: ["contradiction", "shadhdh"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the shādhdh",
    en: ["Ibn al-Ṣalāḥ quotes al-Shāfiʿī's definition of the shādhdh. What is its key point?", ["A reliable narrator contradicting what others narrate", "Any report that only one reliable narrator transmits", "A weak narrator's report that nobody else transmits", "A report whose text contains strange vocabulary"], "Al-Shāfiʿī said the shādhdh is not that a reliable narrator reports what others do not, but that he reports something contrary to what people narrate. This makes contradiction, not solitariness, the decisive element."],
    de: ["Ibn al-Ṣalāḥ zitiert al-Shāfiʿīs Definition des Shādhdh. Was ist ihr Kernpunkt?", ["Ein Zuverlässiger widerspricht dem, was andere überliefern", "Jeder Bericht, den nur ein Zuverlässiger allein weitergibt", "Der Bericht eines Schwachen, den sonst niemand weitergibt", "Ein Bericht, dessen Text ungewöhnliche Wörter enthält"], "Al-Shāfiʿī sagte, Shādhdh sei nicht, dass ein Zuverlässiger etwas überliefert, was andere nicht überliefern, sondern dass er etwas überliefert, das dem widerspricht, was die Leute überliefern. Damit ist der Widerspruch, nicht das Alleinsein, entscheidend."],
    ar: ["نقل ابن الصلاح تعريف الشافعي للشاذ، فما جوهره؟", ["مخالفة الثقة لما رواه الناس", "كل حديث تفرد به ثقة واحد", "حديث ضعيف لم يروه أحد غيره", "حديث في متنه ألفاظ غريبة نادرة"], "قال الشافعي: ليس الشاذ أن يروي الثقة ما لا يروي غيره، إنما الشاذ أن يروي الثقة حديثًا يخالف ما روى الناس، فجعل المخالفة هي المعتبرة لا مجرد التفرد."] },

  { id: "hdt-062", s: "hadith", g: 4, d: 5, t: ["sahih", "comparative-views", "muqaddima-ibn-al-salah"], tr: ["comparative"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ṣaḥīḥ; al-Nawawī, al-Taqrīb wa-l-Taysīr, the type on the ṣaḥīḥ",
    en: ["Which statement correctly describes the discussion about authenticating hadith in later centuries?", ["Ibn al-Ṣalāḥ discouraged independent later grading; al-Nawawī allowed it to the qualified", "Ibn al-Ṣalāḥ allowed anyone to grade hadith; al-Nawawī forbade it to all later scholars", "Both held that no grading made after the time of al-Bukhārī can be valid at all", "Al-Nawawī forbade all later grading; Ibn al-Ṣalāḥ required it of every single jurist"], "Ibn al-Ṣalāḥ was cautious about independent taṣḥīḥ in his time and directed students to gradings of earlier imams. Al-Nawawī answered that it is permissible for one who is capable and has strong knowledge, and later scholars generally followed him."],
    de: ["Welche Aussage beschreibt die Diskussion über die Authentifizierung von Hadithen in späteren Jahrhunderten richtig?", ["Ibn al-Ṣalāḥ riet von selbständigem späterem Bewerten ab; al-Nawawī erlaubte es Befähigten", "Ibn al-Ṣalāḥ erlaubte jedem das Bewerten; al-Nawawī verbot es allen späteren Gelehrten", "Beide hielten jede Bewertung nach der Zeit al-Bukhārīs grundsätzlich für ungültig", "Al-Nawawī verbot jedes spätere Bewerten; Ibn al-Ṣalāḥ verlangte es von jedem Rechtsgelehrten"], "Ibn al-Ṣalāḥ war gegenüber selbständigem Taṣḥīḥ in seiner Zeit zurückhaltend und verwies auf die Bewertungen früherer Imame. Al-Nawawī entgegnete, es sei für den Befähigten mit gefestigtem Wissen erlaubt, und spätere Gelehrte folgten meist ihm."],
    ar: ["أي العبارات تصف الخلاف في التصحيح في العصور المتأخرة وصفًا صحيحًا؟", ["استبعد ابن الصلاح استقلال المتأخر بالتصحيح، وجوّزه النووي للمتمكن", "أجاز ابن الصلاح التصحيح لكل أحد، ومنعه النووي على كل المتأخرين", "رأى كلاهما أنه لا يصح أي تصحيح بعد عصر البخاري", "منع النووي كل تصحيح متأخر، وأوجبه ابن الصلاح على كل فقيه"], "تعذّر عند ابن الصلاح في زمانه الاستقلال بإدراك الصحيح بمجرد اعتبار الأسانيد، فأحال على ما نص عليه الأئمة، وقال النووي: الأظهر عندي جوازه لمن تمكن وقويت معرفته، وعلى ذلك عمل المتأخرين."] },

  { id: "hdt-063", s: "hadith", g: 4, d: 4, t: ["tadlis", "broken-chain"], src: "al-Suyūṭī, Tadrīb al-Rāwī, the type on tadlīs",
    en: ["What is tadlīs al-taswiya, often considered the worst kind of tadlīs?", ["Dropping a weak narrator between two reliable ones", "Calling one's own teacher by an obscure, unused kunya", "Narrating from a contemporary one never actually met", "Shortening a long text without indicating the omission"], "In taswiya the mudallis removes a weak narrator not from his own position but further up, between two reliable narrators who had met, so the whole chain appears reliable. It deceives the critic about a narrator he cannot see."],
    de: ["Was ist Tadlīs al-Taswiya, das oft als schlimmste Art des Tadlīs gilt?", ["Das Weglassen eines Schwachen zwischen zwei Zuverlässigen", "Das Benennen des eigenen Lehrers mit einer unbekannten Kunya", "Das Überliefern von einem Zeitgenossen, den man nie traf", "Das Kürzen eines langen Textes ohne Hinweis auf die Auslassung"], "Bei der Taswiya entfernt der Mudallis einen Schwachen nicht an seiner eigenen Stelle, sondern weiter oben zwischen zwei Zuverlässigen, die einander begegnet waren, sodass die ganze Kette zuverlässig erscheint. So wird der Kritiker über einen Überlieferer getäuscht, den er nicht sieht."],
    ar: ["ما تدليس التسوية الذي يعد من شر أنواع التدليس؟", ["إسقاط ضعيف بين ثقتين ليستوي الإسناد", "تكنية الراوي شيخه بكنية غير مشهورة", "الرواية عن معاصر لم يلقه قط", "اختصار المتن الطويل دون بيان الحذف"], "تدليس التسوية أن يسقط المدلس ضعيفًا لا من بينه وبين شيخه بل من فوق، بين ثقتين لقي أحدهما الآخر، فيستوي الإسناد كله ثقات في الظاهر، فيخفى على الناقد حال الساقط."] },

  { id: "hdt-064", s: "hadith", g: 4, d: 4, t: ["key-works", "history-of-the-science"], src: "Ibn Ḥajar, Nuzhat al-Naẓar, introduction",
    en: ["Which work does Ibn Ḥajar name at the head of the earliest writings on hadith terminology?", ["al-Muḥaddith al-Fāṣil by al-Rāmahurmuzī", "Maʿrifat ʿUlūm al-Ḥadīth by al-Ḥākim", "al-Kifāya fī ʿIlm al-Riwāya by al-Khaṭīb", "al-Ilmāʿ by al-Qāḍī ʿIyāḍ"], "In the preface to Nuzhat al-Naẓar, Ibn Ḥajar names among the first to write on the subject al-Qāḍī Abū Muḥammad al-Rāmahurmuzī in al-Muḥaddith al-Fāṣil, though it was not comprehensive. Al-Ḥākim and al-Khaṭīb came after him."],
    de: ["Welches Werk nennt Ibn Ḥajar an der Spitze der frühesten Schriften über die Hadith-Fachbegriffe?", ["al-Muḥaddith al-Fāṣil von al-Rāmahurmuzī", "Maʿrifat ʿUlūm al-Ḥadīth von al-Ḥākim", "al-Kifāya fī ʿIlm al-Riwāya von al-Khaṭīb", "al-Ilmāʿ von al-Qāḍī ʿIyāḍ"], "Im Vorwort zu Nuzhat al-Naẓar nennt Ibn Ḥajar als einen der Ersten, die darüber schrieben, al-Qāḍī Abū Muḥammad al-Rāmahurmuzī mit al-Muḥaddith al-Fāṣil, wenn auch nicht umfassend. Al-Ḥākim und al-Khaṭīb folgten nach ihm."],
    ar: ["ما الكتاب الذي ذكره ابن حجر في مقدمة أوائل ما صُنف في اصطلاح أهل الحديث؟", ["المحدث الفاصل للرامهرمزي", "معرفة علوم الحديث للحاكم", "الكفاية في علم الرواية للخطيب", "الإلماع للقاضي عياض"], "ذكر ابن حجر في مقدمة نزهة النظر أن من أول من صنف في ذلك القاضي أبو محمد الرامهرمزي في كتابه المحدث الفاصل لكنه لم يستوعب، ثم الحاكم، ثم الخطيب البغدادي."] },

  { id: "hdt-065", s: "hadith", g: 4, d: 4, t: ["key-works", "muqaddima-ibn-al-salah"], src: "al-Suyūṭī, Tadrīb al-Rāwī, introduction",
    en: ["Al-Suyūṭī's Tadrīb al-Rāwī is a commentary on which work?", ["Al-Nawawī's al-Taqrīb, abridging Ibn al-Ṣalāḥ", "Ibn Ḥajar's Nukhbat al-Fikar on hadith terms", "Al-ʿIrāqī's verse rendering of Ibn al-Ṣalāḥ", "Al-Bayqūnī's short poem on the hadith terms"], "Al-Nawawī abridged Ibn al-Ṣalāḥ's Muqaddima in al-Irshād and then further in al-Taqrīb wa-l-Taysīr; al-Suyūṭī wrote Tadrīb al-Rāwī as its commentary. Ibn Ḥajar himself commented on the Nukhba in Nuzhat al-Naẓar."],
    de: ["Zu welchem Werk ist al-Suyūṭīs Tadrīb al-Rāwī ein Kommentar?", ["Al-Nawawīs al-Taqrīb, eine Kürzung Ibn al-Ṣalāḥs", "Ibn Ḥajars Nukhbat al-Fikar über die Hadith-Begriffe", "Al-ʿIrāqīs Versfassung des Werkes Ibn al-Ṣalāḥs", "Al-Bayqūnīs kurzes Gedicht über die Hadith-Begriffe"], "Al-Nawawī kürzte Ibn al-Ṣalāḥs Muqaddima in al-Irshād und weiter in al-Taqrīb wa-l-Taysīr; al-Suyūṭī schrieb dazu Tadrīb al-Rāwī als Kommentar. Ibn Ḥajar selbst kommentierte die Nukhba in Nuzhat al-Naẓar."],
    ar: ["تدريب الراوي للسيوطي شرح لأي كتاب؟", ["التقريب للنووي المختصر من كتاب ابن الصلاح", "نخبة الفكر لابن حجر في مصطلح الحديث", "ألفية العراقي في نظم كتاب ابن الصلاح", "المنظومة البيقونية في مصطلح الحديث"], "اختصر النووي مقدمة ابن الصلاح في الإرشاد ثم في التقريب والتيسير، وشرح السيوطي التقريب في تدريب الراوي، وأما النخبة فشرحها ابن حجر نفسه في نزهة النظر."] },

  { id: "hdt-066", s: "hadith", g: 4, d: 5, t: ["hasan", "definitions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ḥasan; al-Khaṭṭābī, Maʿālim al-Sunan, introduction",
    en: ["Ibn al-Ṣalāḥ quotes a definition of ḥasan as a report 'whose source is known and whose narrators are well known'. Whose definition is this?", ["Al-Khaṭṭābī", "Al-Tirmidhī", "Ibn al-Jawzī", "Al-Ḥākim al-Naysābūrī"], "This definition is al-Khaṭṭābī's, from the introduction of Maʿālim al-Sunan. Al-Tirmidhī's description is different: no narrator accused of lying, not shādhdh, and narrated through more than one route."],
    de: ["Ibn al-Ṣalāḥ zitiert eine Definition des Ḥasan als Bericht, „dessen Ursprung bekannt ist und dessen Überlieferer bekannt sind“. Von wem stammt sie?", ["Von al-Khaṭṭābī", "Von al-Tirmidhī", "Von Ibn al-Jawzī", "Von al-Ḥākim al-Naysābūrī"], "Diese Definition stammt von al-Khaṭṭābī aus der Einleitung zu Maʿālim al-Sunan. Al-Tirmidhīs Beschreibung ist eine andere: kein der Lüge bezichtigter Überlieferer, nicht shādhdh und über mehr als einen Weg überliefert."],
    ar: ["نقل ابن الصلاح في تعريف الحسن أنه «ما عُرف مخرجه واشتهر رجاله»، فلمن هذا التعريف؟", ["الخطابي", "الترمذي", "ابن الجوزي", "الحاكم النيسابوري"], "هذا تعريف الخطابي في مقدمة معالم السنن، وأما الترمذي فوصف الحسن بألا يكون في إسناده متهم بالكذب، ولا يكون شاذًا، ويروى من غير وجه نحو ذلك."] },

  { id: "hdt-067", s: "hadith", g: 4, d: 5, t: ["hasan", "definitions"], src: "al-Tirmidhī, al-ʿIlal al-Ṣaghīr (end of al-Jāmiʿ)",
    en: ["Which set of conditions does al-Tirmidhī give for what he calls ḥasan in his Jāmiʿ?", ["No narrator accused of lying, not shādhdh, more than one route", "A connected chain, fully precise narrators, and no hidden defect", "Narrated by two Companions, with no mudallis anywhere in the chain", "Accepted in practice by the jurists and not contradicting the Quran"], "In al-ʿIlal al-Ṣaghīr at the end of his Jāmiʿ, al-Tirmidhī explains that by ḥasan he means a report without a narrator accused of lying, which is not shādhdh and is narrated through another route as well. This is closer to what later scholars call ḥasan li-ghayrihi."],
    de: ["Welche Bedingungen nennt al-Tirmidhī für das, was er in seinem Jāmiʿ ḥasan nennt?", ["Kein der Lüge bezichtigter Überlieferer, nicht shādhdh und über mehr als einen Weg überliefert", "Eine zusammenhängende Kette, vollständig genaue Überlieferer und kein verborgener Mangel", "Von zwei Gefährten überliefert und ohne Mudallis in der Kette", "Von den Rechtsgelehrten angenommen und dem Koran nicht widersprechend"], "In al-ʿIlal al-Ṣaghīr am Ende seines Jāmiʿ erklärt al-Tirmidhī, mit ḥasan meine er einen Bericht ohne der Lüge bezichtigten Überlieferer, der nicht shādhdh ist und auch über einen anderen Weg überliefert wird. Das steht dem nahe, was Spätere ḥasan li-ghayrihi nennen."],
    ar: ["ما الشروط التي ذكرها الترمذي لما يسميه حسنًا في جامعه؟", ["لا متهم بالكذب في إسناده، ولا شذوذ، ويروى من غير وجه", "اتصال السند، وتمام ضبط الرواة، والسلامة من العلة", "أن يرويه صحابيان، وألا يكون في إسناده مدلس", "أن يعمل به الفقهاء، وألا يخالف ظاهر القرآن"], "بيّن الترمذي في العلل الصغير آخر جامعه أن الحسن عنده ما لا يكون في إسناده من يتهم بالكذب، ولا يكون شاذًا، ويروى من غير وجه نحو ذلك، وهو قريب مما سماه المتأخرون الحسن لغيره."] },

  { id: "hdt-068", s: "hadith", g: 4, d: 4, t: ["companions", "history-of-the-science"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the Companions",
    en: ["Who is commonly named as the last Companion to die, without exception of region?", ["Abū al-Ṭufayl ʿĀmir ibn Wāthila", "Anas ibn Mālik al-Anṣārī", "Sahl ibn Saʿd al-Sāʿidī", "ʿAbd Allāh ibn ʿUmar ibn al-Khaṭṭāb"], "Ibn al-Ṣalāḥ and others state that Abū al-Ṭufayl was the last Companion to die anywhere. Anas ibn Mālik is named as the last in Basra and Sahl ibn Saʿd among the last in Medina."],
    de: ["Wer wird gemeinhin als der zuletzt verstorbene Gefährte überhaupt genannt?", ["Abū al-Ṭufayl ʿĀmir ibn Wāthila", "Anas ibn Mālik al-Anṣārī", "Sahl ibn Saʿd al-Sāʿidī", "ʿAbd Allāh ibn ʿUmar ibn al-Khaṭṭāb"], "Ibn al-Ṣalāḥ und andere geben an, dass Abū al-Ṭufayl als letzter Gefährte überhaupt starb. Anas ibn Mālik gilt als der letzte in Basra und Sahl ibn Saʿd als einer der letzten in Medina."],
    ar: ["من الذي يُذكر عادةً أنه آخر الصحابة موتًا على الإطلاق؟", ["أبو الطفيل عامر بن واثلة", "أنس بن مالك الأنصاري", "سهل بن سعد الساعدي", "عبد الله بن عمر بن الخطاب"], "ذكر ابن الصلاح وغيره أن آخر الصحابة موتًا على الإطلاق أبو الطفيل عامر بن واثلة، وأما أنس بن مالك فآخر من مات بالبصرة، وسهل بن سعد من آخر من مات بالمدينة."] },

  { id: "hdt-069", s: "hadith", g: 4, d: 4, t: ["sahih", "sahih-conditions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on the ḥasan, remarks on 'ṣaḥīḥ al-isnād'",
    en: ["Why does Ibn al-Ṣalāḥ consider the verdict 'ṣaḥīḥ al-isnād' weaker than the verdict 'ṣaḥīḥ'?", ["The chain may be sound while the text is shādhdh or defective", "It means that the chain has at least one unknown narrator in it", "It is used only for those reports that stop at a Companion", "It means the report is mutawātir but its wording is weak"], "'Ṣaḥīḥ al-isnād' affirms only the conditions of the chain: connection, uprightness and precision. Freedom from shudhūdh and ʿilla in the text is not thereby guaranteed, unless a reliable imam uses the phrase without noting any defect."],
    de: ["Warum hält Ibn al-Ṣalāḥ das Urteil „ṣaḥīḥ al-isnād“ für schwächer als das Urteil „ṣaḥīḥ“?", ["Die Kette kann gesund sein, während der Text shādhdh oder mangelhaft ist", "Es bedeutet, dass in der Kette mindestens ein unbekannter Überlieferer steht", "Es wird nur für solche Berichte verwendet, die bei einem Gefährten enden", "Es bedeutet, dass der Bericht mutawātir ist, sein Wortlaut aber schwach"], "„Ṣaḥīḥ al-isnād“ bestätigt nur die Bedingungen der Kette: Zusammenhang, Rechtschaffenheit und Genauigkeit. Die Freiheit des Textes von Shudhūdh und ʿIlla ist damit nicht gesichert, es sei denn, ein verlässlicher Imam verwendet die Wendung, ohne einen Mangel zu erwähnen."],
    ar: ["لماذا جعل ابن الصلاح قولهم «صحيح الإسناد» دون قولهم «حديث صحيح»؟", ["لأنه قد يصح الإسناد ويكون المتن شاذًا أو معللًا", "لأنه يعني أن في سنده راويًا مجهولًا لم يوثق", "لأنه لا يقال إلا فيما وقف على الصحابي وحده", "لأنه يعني أن الحديث متواتر ولكن لفظه ضعيف"], "قولهم صحيح الإسناد إثبات لشروط السند من اتصال وعدالة وضبط، ولا يلزم منه سلامة المتن من الشذوذ والعلة، إلا أن يطلقه إمام معتمد ولا يذكر له علة فالظاهر صحة المتن."] },

  { id: "hdt-070", s: "hadith", g: 4, d: 4, t: ["sanad-matn", "history-of-the-science"], src: "Muslim, Ṣaḥīḥ Muslim, Muqaddima, on the isnād being part of the religion",
    en: ["The statement that the isnād is part of the religion, recorded in the introduction of Ṣaḥīḥ Muslim, is attributed to whom?", ["ʿAbd Allāh ibn al-Mubārak", "Muḥammad ibn Sīrīn al-Baṣrī", "Sufyān ibn Saʿīd al-Thawrī", "Aḥmad ibn Muḥammad ibn Ḥanbal"], "Muslim records from ʿAbd Allāh ibn al-Mubārak that the isnād is part of the religion, and that without it anyone could say whatever he wished. In the same introduction Muslim records from Ibn Sīrīn that this knowledge is religion, so one should look to whom one takes it from."],
    de: ["Wem wird der in der Einleitung des Ṣaḥīḥ Muslim überlieferte Ausspruch zugeschrieben, der Isnād sei Teil der Religion?", ["ʿAbd Allāh ibn al-Mubārak", "Muḥammad ibn Sīrīn al-Baṣrī", "Sufyān ibn Saʿīd al-Thawrī", "Aḥmad ibn Muḥammad ibn Ḥanbal"], "Muslim überliefert von ʿAbd Allāh ibn al-Mubārak, der Isnād sei Teil der Religion, und ohne ihn könne jeder sagen, was er wolle. In derselben Einleitung überliefert Muslim von Ibn Sīrīn, dieses Wissen sei Religion, man solle also schauen, von wem man es nimmt."],
    ar: ["إلى من يُنسب القول بأن الإسناد من الدين، كما في مقدمة صحيح مسلم؟", ["عبد الله بن المبارك", "محمد بن سيرين البصري", "سفيان بن سعيد الثوري", "أحمد بن محمد بن حنبل"], "روى مسلم في مقدمة صحيحه عن عبد الله بن المبارك قوله: الإسناد من الدين، ولولا الإسناد لقال من شاء ما شاء، وروى فيها عن ابن سيرين: إن هذا العلم دين فانظروا عمن تأخذون دينكم."] },

  { id: "hdt-071", s: "hadith", g: 4, d: 5, t: ["contradiction", "added-wording"], src: "Ibn Ḥajar, Nukhbat al-Fikar, on the addition of a reliable narrator",
    en: ["According to Ibn Ḥajar's Nukhbat al-Fikar, when is an addition (ziyāda) by a narrator of ṣaḥīḥ or ḥasan reports accepted?", ["As long as it does not conflict with a more reliable report", "Only if every other narrator of the report also mentions it", "Only if it occurs in the text and not anywhere in the chain", "Always, regardless of what the other narrators reported"], "Ibn Ḥajar states that the addition of such a narrator is accepted unless it is incompatible with the report of someone more reliable; if it is, the preferred report is maḥfūẓ and the other shādhdh. He adds that accepting every addition without distinction does not fit the hadith scholars, who require that the ṣaḥīḥ not be shādhdh."],
    de: ["Wann wird nach Ibn Ḥajars Nukhbat al-Fikar ein Zusatz (Ziyāda) eines Überlieferers von Ṣaḥīḥ- oder Ḥasan-Berichten angenommen?", ["Solange er nicht dem Bericht eines Zuverlässigeren widerspricht", "Nur wenn alle anderen Überlieferer ihn ebenfalls erwähnen", "Nur wenn er im Text und nicht in der Kette steht", "Immer, unabhängig davon, was die anderen überlieferten"], "Ibn Ḥajar stellt fest, dass der Zusatz eines solchen Überlieferers angenommen wird, sofern er mit dem Bericht eines Zuverlässigeren nicht unvereinbar ist; andernfalls ist der bevorzugte Bericht maḥfūẓ und der andere shādhdh. Er fügt hinzu, dass die unterschiedslose Annahme jedes Zusatzes nicht zu den Hadith-Gelehrten passt, die verlangen, dass das Ṣaḥīḥ nicht shādhdh ist."],
    ar: ["متى تقبل زيادة راوي الصحيح والحسن بحسب نخبة الفكر لابن حجر؟", ["ما لم تناف رواية من هو أوثق منه", "إذا ذكرها جميع الرواة الآخرين للحديث", "إذا كانت في المتن دون الإسناد خاصة", "مطلقًا مهما روى غيره من الرواة"], "قال ابن حجر: وزيادة راويهما مقبولة ما لم تقع منافية لمن هو أوثق، فإن خولف بأرجح فالراجح المحفوظ ومقابله الشاذ، ونبه على أن القول بقبول الزيادة مطلقًا لا يتأتى على طريقة المحدثين الذين يشترطون في الصحيح ألا يكون شاذًا."] },

  { id: "hdt-072", s: "hadith", g: 4, d: 4, t: ["jarh-tadil", "narrator-conditions"], src: "Ibn al-Ṣalāḥ, Muqaddima, the type on reliable narrators who became confused (al-mukhtaliṭūn)",
    en: ["A reliable narrator suffers ikhtilāṭ (deterioration of memory) late in life. How are his reports treated?", ["Reports heard before the decline are accepted; later or unclear ones are not", "All of his reports are rejected, including those he narrated earlier", "All of his reports are accepted, since he was once a reliable narrator", "Only the reports heard from him by his own sons are accepted"], "Ibn al-Ṣalāḥ explains that what was taken from a mukhtaliṭ before his confusion is accepted, while what was taken afterwards, or where the timing is unclear, is not. Critics therefore record which students heard from him early."],
    de: ["Ein zuverlässiger Überlieferer erleidet im Alter Ikhtilāṭ (Verfall des Gedächtnisses). Wie werden seine Berichte behandelt?", ["Vor dem Verfall Gehörtes wird angenommen, Späteres oder Ungeklärtes nicht", "Alle seine Berichte werden abgelehnt, auch die früher gehörten", "Alle seine Berichte werden angenommen, da er einst zuverlässig war", "Nur die von seinen eigenen Söhnen gehörten Berichte werden angenommen"], "Ibn al-Ṣalāḥ erklärt, dass das, was vor der Verwirrung von einem Mukhtaliṭ aufgenommen wurde, angenommen wird, das danach oder zeitlich Ungeklärte jedoch nicht. Die Kritiker verzeichnen deshalb, welche Schüler früh von ihm hörten."],
    ar: ["ثقة اختلط في آخر عمره، فما حكم مروياته؟", ["يقبل ما رُوي عنه قبل الاختلاط دون ما بعده أو ما أُشكل", "ترد جميع مروياته حتى ما سُمع منه قبل الاختلاط", "تقبل جميع مروياته لأنه كان ثقة قبل ذلك", "لا يقبل من حديثه إلا ما رواه عنه أبناؤه"], "ذكر ابن الصلاح أن ما أُخذ عن المختلط قبل الاختلاط مقبول، وما أُخذ بعده أو أُشكل أمره فلا يقبل، ولذلك يعتني النقاد بتمييز من سمع منه قديمًا ممن سمع منه بعد الاختلاط."] },
];
